<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>Rechner</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #ffffff; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h2 id="title">Rechner</h2>
  <input id="a" type="number" placeholder="Erste Zahl">
  <input id="b" type="number" placeholder="Zweite Zahl">
  <div id="ops" class="box row">
    <button id="add">+</button>
    <button id="sub">−</button>
    <button id="mul">×</button>
    <button id="div">÷</button>
  </div>
  <h2 id="out"></h2>
  <script>
    document.getElementById("add").addEventListener('click', function () {
      document.getElementById("out").textContent = 'Ergebnis: ' + String((parseFloat(document.getElementById("a").value) || 0) + (parseFloat(document.getElementById("b").value) || 0));
    });
    document.getElementById("sub").addEventListener('click', function () {
      document.getElementById("out").textContent = 'Ergebnis: ' + String((parseFloat(document.getElementById("a").value) || 0) - (parseFloat(document.getElementById("b").value) || 0));
    });
    document.getElementById("mul").addEventListener('click', function () {
      document.getElementById("out").textContent = 'Ergebnis: ' + String((parseFloat(document.getElementById("a").value) || 0) * (parseFloat(document.getElementById("b").value) || 0));
    });
    document.getElementById("div").addEventListener('click', function () {
      if ((parseFloat(document.getElementById("b").value) || 0) == 0) {
        document.getElementById("out").textContent = 'Teilen durch 0 geht nicht';
      } else {
        document.getElementById("out").textContent = 'Ergebnis: ' + String(Math.round(((parseFloat(document.getElementById("a").value) || 0) / (parseFloat(document.getElementById("b").value) || 0)) * 100) / 100);
      }
    });
  </script>
</body>
</html>

```

