```html
<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>신호등</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #e5e7eb; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    input { font-size: 18px; padding: 8px; margin: 4px; }
  </style>
</head>
<body>
  <h1>신호등</h1>
  <div id="light" style="width: 100px; height: 100px; border-radius: 50%; background: red; margin: 20px auto"></div>
  <p id="text">멈춰요!</p>
  <button id="next">다음 신호</button>
  <script>
    function beep() {
      const audio = new (window.AudioContext || window.webkitAudioContext)();
      const osc = audio.createOscillator();
      osc.connect(audio.destination);
      osc.frequency.value = 523;
      osc.start();
      osc.stop(audio.currentTime + 0.15);
    }

    const states = [['red', '멈춰요!'], ['green', '건너가요!'], ['yellow', '조심해요!']];
    let i = 0;
    document.getElementById('next').addEventListener('click', function () {
      beep();
      i = (i + 1) % states.length;
      document.getElementById('light').style.background = states[i][0];
      document.getElementById('text').textContent = states[i][1];
    });
  </script>
</body>
</html>
