    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <div id="stage" class="box" style="background:#ffffff">
    <h2 id="title">배경색 바꾸기</h2>
    <div id="btns" class="box row">
      <button id="rnd">랜덤 색</button>
      <button id="red">빨강</button>
      <button id="blue">파랑</button>
      <button id="green">초록</button>
    </div>
  </div>
  <script>
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    document.getElementById("rnd").addEventListener('click', function () {
      __beep(329.63, 0.08);
      document.getElementById("stage").style.background = 'hsl(' + Math.floor(Math.random() * 360) + ', 80%, 60%)';
    });
    document.getElementById("red").addEventListener('click', function () {
      __beep(329.63, 0.08);
      document.getElementById("stage").style.background = "#ef4444";
    });
    document.getElementById("blue").addEventListener('click', function () {
      __beep(329.63, 0.08);
      document.getElementById("stage").style.background = "#3b82f6";
    });
    document.getElementById("green").addEventListener('click', function () {
      __beep(329.63, 0.08);
      document.getElementById("stage").style.background = "#22c55e";
    });
  </script>
</body>
</html>
