  <h2 id="title1">🌈 무지개</h2>
  <canvas id="cv" width="280" height="140"></canvas>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __pen(name) { return $(name).getContext('2d'); }
    function __rect(name, x, y, w, h, color) { var g = __pen(name); g.fillStyle = color; g.fillRect(x, y, w, h); }

    var cols, i;

    cols = ["#ef4444", "#f97316", "#facc15", "#22c55e", "#38bdf8", "#3b82f6", "#a855f7"];
    for (i = 0; i <= 6; i++) {
      __rect("cv", 0, i * 20, 280, 20, cols[((i + 1) - 1)]);
    }
  </script>
</body>
</html>

```

