<head>
  <meta charset="UTF-8">
  <title>알람 시계</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #0f172a; color: #f1f5f9; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h1 id="now">--:--</h1>
  <div id="in" class="box row">
    <input id="hh" type="number" placeholder="시">
    <input id="mm" type="number" placeholder="분">
  </div>
  <button id="set">알람 맞추기</button>
  <p id="info"></p>
  <script>
    var __timers = [];
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var on, ah, am;

    document.getElementById("set").addEventListener('click', function () {
      ah = (parseFloat(document.getElementById("hh").value) || 0);
      am = (parseFloat(document.getElementById("mm").value) || 0);
      on = true;
      document.getElementById("info").textContent = ['알람: ',ah,':',am < 10 ? '0' + String(am) : am].join('');
    });
    __timers.push(setInterval(function () {
      document.getElementById("now").textContent = [new Date().getHours() < 10 ? '0' + String(new Date().getHours()) : new Date().getHours(),':',new Date().getMinutes() < 10 ? '0' + String(new Date().getMinutes()) : new Date().getMinutes(),':',new Date().getSeconds() < 10 ? '0' + String(new Date().getSeconds()) : new Date().getSeconds()].join('');
      if (on && new Date().getHours() == ah && new Date().getMinutes() == am) {
        on = false;
        __beep(523.25, 1);
        alert('⏰ 일어나요!');
      }
    }, 1000));

    on = false;
  </script>
</body>
</html>
