<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>암산 스피드</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #eff6ff; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    input { font-size: 26px; padding: 8px; margin: 4px; width: 120px; text-align: center; }
    #problem { font-size: 52px; font-weight: bold; margin: 12px; min-height: 64px; }
    #msg { font-size: 22px; font-weight: bold; min-height: 28px; }
  </style>
</head>
<body>
  <h1>🧮 암산 스피드 30초</h1>
  <p>맞힌 개수: <span id="score">0</span> · 남은 시간: <span id="time">30</span>초</p>
  <div id="problem">준비!</div>
  <input id="answer" type="number" disabled>
  <p id="msg">답을 쓰고 엔터!</p>
  <button id="start">시작</button>
  <script>
    const input = document.getElementById('answer');
    const msg = document.getElementById('msg');
    let a = 0, b = 0, op = '+';
    let score = 0;
    let timeLeft = 30;
    let running = false;
    let timer = null;

    function newProblem() {
      op = Math.random() < 0.5 ? '+' : '-';
      a = Math.floor(Math.random() * 50) + 1;
      b = Math.floor(Math.random() * 50) + 1;
      if (op === '-' && b > a) {
        const t = a; a = b; b = t; // 빼기는 답이 음수가 안 되게
      }
      document.getElementById('problem').textContent = a + ' ' + op + ' ' + b + ' = ?';
      input.value = '';
    }

    function correctAnswer() {
      return op === '+' ? a + b : a - b;
    }

    function startGame() {
      clearInterval(timer);
      score = 0;
      timeLeft = 30;
      running = true;
      input.disabled = false;
      input.focus();
      msg.textContent = '';
      document.getElementById('score').textContent = 0;
      document.getElementById('time').textContent = 30;
      document.getElementById('start').textContent = '다시 시작';
      newProblem();
      timer = setInterval(function () {
        if (!running) return;
        timeLeft -= 1;
        document.getElementById('time').textContent = timeLeft;
        if (timeLeft <= 0) endGame();
      }, 1000);
    }

    function endGame() {
      running = false;
      clearInterval(timer);
      timer = null;
      timeLeft = 0;
      document.getElementById('time').textContent = 0;
      input.disabled = true;
      document.getElementById('problem').textContent = '끝!';
      msg.textContent = '⏰ 게임 끝! 30초 동안 ' + score + '문제 맞혔어요';
    }

    input.addEventListener('keydown', function (e) {
      if (e.key !== 'Enter' || !running || input.value === '') return;
      if (Number(input.value) === correctAnswer()) {
        score += 1;
        document.getElementById('score').textContent = score;
        msg.textContent = '⭕';
        newProblem();
      } else {
        msg.textContent = '❌ 다시 해 봐요';
        input.value = '';
      }
    });
    document.getElementById('start').addEventListener('click', startGame);
  </script>
</body>
</html>
