<body>
  <h2 id="score">점수: 0</h2>
  <h1 id="q"></h1>
  <input id="ans" type="number" placeholder="답">
  <button id="ok">확인</button>
  <p id="msg"></p>
  <script>
    var pts, a, b;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function nq() {
      a = mathRandomInt(2, 9);
      b = mathRandomInt(1, 9);
      document.getElementById("q").textContent = [a,' × ',b,' = ?'].join('');
      document.getElementById("ans").value = '';
    }

    document.getElementById("ok").addEventListener('click', function () {
      if ((parseFloat(document.getElementById("ans").value) || 0) == a * b) {
        pts = (typeof pts === 'number' ? pts : 0) + 1;
        document.getElementById("score").textContent = '점수: ' + String(pts);
        document.getElementById("msg").textContent = '정답!';
        nq();
      } else {
        document.getElementById("msg").textContent = '틀렸어요. 정답은 ' + String(a * b);
      }
    });

    pts = 0;
    nq();
  </script>
</body>
</html>
