  <h2 id="menuText">?</h2>
  <button id="pickBtn">골라 줘</button>
  <script>
    var menus, pick, last;

    function listsGetRandomItem(list, remove) {
      var x = Math.floor(Math.random() * list.length);
      if (remove) {
        return list.splice(x, 1)[0];
      } else {
        return list[x];
      }
    }

    document.getElementById("pickBtn").addEventListener('click', function () {
      pick = listsGetRandomItem(menus, false);
      while (pick == last) {
        pick = listsGetRandomItem(menus, false);
      }
      last = pick;
      document.getElementById("menuText").textContent = pick;
    });

    menus = ['김치찌개', '돈까스', '비빔밥', '라면', '초밥'];
    last = '';
  </script>
