  <div id="r" class="box row">
    <input id="book" type="text" placeholder="Book title">
    <button id="add">Add</button>
  </div>
  <ul id="books"></ul>
  <h3 id="count">Books read: 0</h3>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var n;

    document.getElementById("add").addEventListener('click', function () {
      if (!!document.getElementById("book").value.length) {
        n = (typeof n === 'number' ? n : 0) + 1;
        __add("books", [n,'. ',document.getElementById("book").value].join(''));
        document.getElementById("book").value = '';
        document.getElementById("count").textContent = 'Books read: ' + String(n);
      }
    });

    n = 0;
  </script>
</body>
</html>
