  <button id="go">돌리기 🎰</button>
  <h3 id="result"></h3>
  <script>
    var __timers = [];
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var menu, spins;

    function listsGetRandomItem(list, remove) {
      var x = Math.floor(Math.random() * list.length);
      if (remove) {
        return list.splice(x, 1)[0];
      } else {
        return list[x];
      }
    }

    document.getElementById("go").addEventListener('click', function () {
      if (spins <= 0) {
        spins = 20;
        document.getElementById("result").textContent = '';
      }
    });
    __timers.push(setInterval(function () {
      if (spins > 0) {
        spins = (typeof spins === 'number' ? spins : 0) + -1;
        document.getElementById("show").textContent = listsGetRandomItem(menu, false);
        __beep(440.00, 0.03);
        if (spins == 0) {
          document.getElementById("result").textContent = '오늘의 메뉴: ' + String(document.getElementById("show").textContent);
          document.getElementById("show").style.color = "#ef4444";
          __beep(523.25, 0.4);
        } else {
          document.getElementById("show").style.color = "#111111";
        }
      }
    }, 100));

    menu = ['김치찌개', '돈까스', '짜장면', '비빔밥', '떡볶이', '초밥'];
    spins = 0;
  </script>
</body>
</html>
