    var 정답, 횟수;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("확인버튼").addEventListener('click', function () {
      횟수 = (typeof 횟수 === 'number' ? 횟수 : 0) + 1;
      if ((parseFloat(document.getElementById("입력칸").value) || 0) == 정답) {
        document.getElementById("결과").textContent = ['정답! ',횟수,'번 만에 맞혔어요'].join('');
