    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }
    function __size(name, prop, v) {
      var s = $(name).style;
      if (prop === 'opacity') s.opacity = v / 100;
      else if (prop === 'rotate') s.transform = 'rotate(' + v + 'deg)';
      else s[prop] = v + 'px';
    }

    var sum, pc;

    document.getElementById("addBtn").addEventListener('click', function () {
      if (!document.getElementById("book").value.trim().length || (parseFloat(document.getElementById("pages").value) || 0) <= 0) {
        document.getElementById("msg").textContent = '제목과 쪽수를 써 주세요';
