        document.getElementById("msg").textContent = '';
        __add("log", [document.getElementById("book").value.trim(),' - ',(parseFloat(document.getElementById("pages").value) || 0),'쪽'].join(''));
        sum = (typeof sum === 'number' ? sum : 0) + (parseFloat(document.getElementById("pages").value) || 0);
        document.getElementById("total").textContent = ['총 ',sum,'쪽'].join('');
        pc = Math.min(Math.max(Math.round((sum * 100) / 300), 0), 100);
        __size("bar", "width", pc * 3);
        document.getElementById("pct").textContent = String(pc) + '%';
        if (sum >= 300) {
          document.getElementById("goal").textContent = '🎉 목표 달성!';
        } else {
          document.getElementById("goal").textContent = ['목표까지 ',300 - sum,'쪽'].join('');
        }
        document.getElementById("book").value = '';
        document.getElementById("pages").value = '';
      }
    });

    sum = 0;
    __size("bar", "width", 0);
  </script>
