      on = false;
    });
    __timers.push(setInterval(function () {
      if (on) {
        t = (typeof t === 'number' ? t : 0) + -1;
        document.getElementById("time").textContent = t;
        if (t <= 5) {
          document.getElementById("time").style.color = "#ef4444";
        }
        if (t == 0) {
          on = false;
          document.getElementById("time").textContent = '끝!';
          __beep(440.00, 0.6);
        }
      }
    }, 1000));

