  <h1 id="res"></h1>
  <p id="left">남은 기회: 5번</p>
  <button id="again">새 게임</button>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var ans, diff, ch;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function newGame() {
      ans = mathRandomInt(1, 20);
      ch = 5;
      document.getElementById("left").textContent = '남은 기회: 5번';
      document.getElementById("res").textContent = '';
      __show("ok", "show");
      __show("again", "hide");
    }

    document.getElementById("ok").addEventListener('click', function () {
      diff = Math.abs((parseFloat(document.getElementById("g").value) || 0) - ans);
      ch = (typeof ch === 'number' ? ch : 0) + -1;
      document.getElementById("left").textContent = ['남은 기회: ',ch,'번'].join('');
      if (diff == 0) {
        document.getElementById("res").textContent = '정답! 🎉';
      } else if (diff <= 3) {
        document.getElementById("res").textContent = '아깝다! 😮';
      } else {
        document.getElementById("res").textContent = '멀었어요 🙅';
      }
      if (diff == 0 || ch == 0) {
        __show("ok", "hide");
        __show("again", "show");
      }
    });
    document.getElementById("again").addEventListener('click', function () {
      newGame();
    });

    newGame();
  </script>
</body>
</html>
