    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h2 id="title">별 받기</h2>
  <canvas id="cv" width="300" height="300"></canvas>
  <div id="info" class="box row">
    <p id="score">점수: 0</p>
    <p id="lives">목숨: 4</p>
  </div>
  <button id="go">시작</button>
  <p id="msg"></p>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    var __timers = [];
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }
    function __pen(name) { return $(name).getContext('2d'); }
    function __clear(name) { var c = $(name); __pen(name).clearRect(0, 0, c.width, c.height); }
    function __rect(name, x, y, w, h, color) { var g = __pen(name); g.fillStyle = color; g.fillRect(x, y, w, h); }
    function __circle(name, x, y, r, color) { var g = __pen(name); g.fillStyle = color; g.beginPath(); g.arc(x, y, Math.max(0, r), 0, Math.PI * 2); g.fill(); }

    var px, score, playing, life, fy, fx;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("go").addEventListener('click', function () {
      score = 0;
      life = 4;
      playing = true;
      fy = 0;
      fx = mathRandomInt(10, 290);
      document.getElementById("msg").textContent = '';
      document.getElementById("score").textContent = '점수: ' + String(0);
      document.getElementById("lives").textContent = '목숨: ' + String(4);
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowLeft") {
        e.preventDefault();
        px = Math.min(Math.max(px - 20, 0), 250);
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowRight") {
        e.preventDefault();
        px = Math.min(Math.max(px + 20, 0), 250);
      }
    });
    __timers.push(setInterval(function () {
      if (playing) {
        fy = (typeof fy === 'number' ? fy : 0) + 9;
        __clear("cv");
        __rect("cv", px, 280, 50, 12, "#a855f7");
        __circle("cv", fx, fy, 10, "#ef4444");
        if (fy >= 275) {
          if (fx >= px && fx <= px + 50) {
            score = (typeof score === 'number' ? score : 0) + 1;
            document.getElementById("score").textContent = '점수: ' + String(score);
            __beep(523.25, 0.1);
          } else {
            life = (typeof life === 'number' ? life : 0) + -1;
            document.getElementById("lives").textContent = '목숨: ' + String(life);
            if (life <= 0) {
              playing = false;
              document.getElementById("msg").textContent = '게임 끝! 점수: ' + String(score);
            }
          }
          fy = 0;
          fx = mathRandomInt(10, 290);
        }
      }
    }, 50));

    px = 125;
    playing = false;
    fy = 0;
    fx = mathRandomInt(10, 290);
  </script>
</body>
</html>
