<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>지뢰찾기</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #f1f5f9; color: #1f2937; padding: 24px; }
    #board { display: grid; grid-template-columns: repeat(9, 34px); gap: 2px; justify-content: center; margin: 16px auto; }
    .cell { width: 34px; height: 34px; padding: 0; font-size: 18px; font-weight: bold; border: none; background: #94a3b8; cursor: pointer; }
    .cell.open { background: #e2e8f0; cursor: default; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>💣 지뢰찾기</h1>
  <p>지뢰 10개 · 깃발: <span id="flags">0</span> · 시간: <span id="time">0</span>초</p>
  <div id="board"></div>
  <p id="msg">클릭: 열기 · 오른쪽 클릭: 깃발</p>
  <button id="restart">다시 시작</button>
  <script>
    const SIZE = 9, MINES = 10;
    const NUM_COLORS = ['', '#2563eb', '#16a34a', '#dc2626', '#7c3aed', '#b45309', '#0891b2', '#000', '#666'];
    const boardEl = document.getElementById('board');
    const msg = document.getElementById('msg');
    let cells = [];   // { mine, open, flag, count, el }
    let opened = 0;
    let flags = 0;
    let seconds = 0;
    let running = false;
    let timer = null;

    function at(r, c) {
      return r >= 0 && r < SIZE && c >= 0 && c < SIZE ? cells[r * SIZE + c] : null;
    }

    function neighbors(r, c) {
      const list = [];
      for (let dr = -1; dr <= 1; dr++) {
        for (let dc = -1; dc <= 1; dc++) {
          if ((dr || dc) && at(r + dr, c + dc)) list.push([r + dr, c + dc]);
        }
      }
      return list;
    }

    function startGame() {
      clearInterval(timer);
      boardEl.innerHTML = '';
      cells = [];
      opened = 0;
      flags = 0;
      seconds = 0;
      running = true;
      msg.textContent = '클릭: 열기 · 오른쪽 클릭: 깃발';
      document.getElementById('flags').textContent = 0;
      document.getElementById('time').textContent = 0;
      for (let i = 0; i < SIZE * SIZE; i++) {
        const el = document.createElement('button');
        el.className = 'cell';
        const r = Math.floor(i / SIZE), c = i % SIZE;
        el.addEventListener('click', function () { reveal(r, c); });
        el.addEventListener('contextmenu', function (e) { e.preventDefault(); toggleFlag(r, c); });
        boardEl.appendChild(el);
        cells.push({ mine: false, open: false, flag: false, count: 0, el: el });
      }
      let placed = 0;
      while (placed < MINES) {
        const cell = cells[Math.floor(Math.random() * cells.length)];
        if (!cell.mine) { cell.mine = true; placed += 1; }
      }
      for (let r = 0; r < SIZE; r++) {
        for (let c = 0; c < SIZE; c++) {
          at(r, c).count = neighbors(r, c).filter(function (p) { return at(p[0], p[1]).mine; }).length;
        }
      }
      timer = setInterval(function () {
        if (!running) return;
        seconds += 1;
        document.getElementById('time').textContent = seconds;
      }, 1000);
    }

    function endGame(text) {
      running = false;
      clearInterval(timer);
      msg.textContent = text;
      cells.forEach(function (cell) { if (cell.mine) cell.el.textContent = '💣'; });
    }

    function reveal(r, c) {
      const cell = at(r, c);
      if (!running || cell.open || cell.flag) return;
      if (cell.mine) {
        cell.el.style.background = '#fca5a5';
        endGame('💥 게임 오버! 지뢰를 밟았어요');
        return;
      }
      cell.open = true;
      opened += 1;
      cell.el.classList.add('open');
      cell.el.textContent = cell.count || '';
      cell.el.style.color = NUM_COLORS[cell.count];
      // 주변에 지뢰가 없으면 이웃 칸도 자동으로 열어요
      if (cell.count === 0) {
        neighbors(r, c).forEach(function (p) { reveal(p[0], p[1]); });
      }
      if (running && opened === SIZE * SIZE - MINES) {
        endGame('🎉 성공! ' + seconds + '초 걸렸어요');
      }
    }

    function toggleFlag(r, c) {
      const cell = at(r, c);
      if (!running || cell.open) return;
      cell.flag = !cell.flag;
      flags += cell.flag ? 1 : -1;
      cell.el.textContent = cell.flag ? '🚩' : '';
      document.getElementById('flags').textContent = flags;
    }

    document.getElementById('restart').addEventListener('click', startGame);
    startGame();
  </script>
</body>
</html>
