      document.getElementById("bal").textContent = String(balance) + '원';
      __save('balance', balance);
      document.getElementById("amt").value = '';
    }

    document.getElementById("dep").addEventListener('click', function () {
      if ((parseFloat(document.getElementById("amt").value) || 0) > 0) {
        balance = (typeof balance === 'number' ? balance : 0) + (parseFloat(document.getElementById("amt").value) || 0);
        document.getElementById("msg").textContent = '입금했어요';
