  <h2 id="st"></h2>
  <script>
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    document.getElementById("play").addEventListener('click', function () {
      document.getElementById("st").textContent = '🎵 연주 중...';
      __beep(261.63, 0.4);
      setTimeout(function () {
        __beep(261.63, 0.4);
      }, (0.5) * 1000);
      setTimeout(function () {
        __beep(392.00, 0.4);
      }, (1) * 1000);
      setTimeout(function () {
        __beep(392.00, 0.4);
      }, (1.5) * 1000);
      setTimeout(function () {
        __beep(440.00, 0.4);
      }, (2) * 1000);
      setTimeout(function () {
        __beep(440.00, 0.4);
      }, (2.5) * 1000);
      setTimeout(function () {
        __beep(392.00, 0.8);
      }, (3) * 1000);
      setTimeout(function () {
        document.getElementById("st").textContent = '';
        document.getElementById("play").textContent = '다시 듣기';
      }, (4) * 1000);
    });

