  <script>
    var menuL;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("pickBtn").addEventListener('click', function () {
      document.getElementById("lunchTx").textContent = menuL[(mathRandomInt(1, menuL.length) - 1)];
    });

    menuL = ['Crêpes', 'Pizza', 'Couscous', 'Quiche', 'Salade', 'Burger'];
