    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h2 id="title">Tirage au sort</h2>
  <div id="in" class="box row">
    <input id="name" type="text" placeholder="Prénom">
    <button id="addBtn">Ajouter</button>
  </div>
  <ul id="names"></ul>
  <button id="pick">Tirer</button>
  <h2 id="out"></h2>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var people;

    function listsGetRandomItem(list, remove) {
      var x = Math.floor(Math.random() * list.length);
      if (remove) {
        return list.splice(x, 1)[0];
      } else {
        return list[x];
      }
    }

    document.getElementById("addBtn").addEventListener('click', function () {
      if (!!document.getElementById("name").value.trim().length) {
        people.push(document.getElementById("name").value.trim());
        __add("names", document.getElementById("name").value.trim());
        document.getElementById("name").value = '';
      }
    });
    document.getElementById("pick").addEventListener('click', function () {
      if (!people.length) {
        document.getElementById("out").textContent = 'Ajoute d\'abord des prénoms';
      } else {
        document.getElementById("out").textContent = 'Tiré au sort : ' + String(listsGetRandomItem(people, false));
      }
    });

    people = [];
  </script>
</body>
</html>

