<body>
  <h2 id="title">Fruit Typing</h2>
  <h1 id="word">-</h1>
  <input id="typed" type="text" placeholder="Type the word and press Enter">
  <div id="info" class="box row">
    <p id="score">Score: 0</p>
    <p id="time">Time: 25</p>
  </div>
  <button id="go">Start</button>
  <p id="best">Best: 0</p>
  <script>
    var __timers = [];

    var words, score, playing, left, hi;

    function listsGetRandomItem(list, remove) {
      var x = Math.floor(Math.random() * list.length);
      if (remove) {
        return list.splice(x, 1)[0];
      } else {
        return list[x];
      }
    }

    document.getElementById("go").addEventListener('click', function () {
      score = 0;
      left = 25;
      playing = true;
      document.getElementById("word").textContent = listsGetRandomItem(words, false);
      document.getElementById("typed").value = '';
      document.getElementById("score").textContent = 'Score: ' + String(0);
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "Enter") {
        e.preventDefault();
        if (playing && document.getElementById("typed").value.trim() == document.getElementById("word").textContent) {
          score = (typeof score === 'number' ? score : 0) + 1;
          document.getElementById("score").textContent = 'Score: ' + String(score);
          document.getElementById("word").textContent = listsGetRandomItem(words, false);
          document.getElementById("typed").value = '';
        }
      }
    });
    __timers.push(setInterval(function () {
      if (playing) {
        left = (typeof left === 'number' ? left : 0) + -1;
        document.getElementById("time").textContent = 'Time: ' + String(left);
        if (left <= 0) {
          playing = false;
          document.getElementById("word").textContent = 'Game over! Score: ' + String(score);
          if (score > hi) {
            hi = score;
            document.getElementById("best").textContent = 'Best: ' + String(hi);
          }
        }
      }
    }, 1000));

    words = ['mango', 'lemon', 'cherry', 'grape', 'melon'];
    playing = false;
    hi = 0;
  </script>
</body>
