<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>Zombie Run</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #111111; color: #f1f5f9; text-align: center; }
  </style>
</head>
<body>
  <h2 id="title">Zombie Run</h2>
  <h3 id="tm">Survived: 0</h3>
  <p id="hint">Keep away from the zombie!</p>
  <h1 id="foe">🧟</h1>
  <h1 id="me">🏃</h1>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __move(name, x, y) {
      var s = $(name).style;
      s.position = 'absolute';
      s.left = x + 'px';
      s.top = y + 'px';
    }
    function __nudge(name, dx, dy) {
      var el = $(name), s = el.style;
      if (s.position !== 'absolute') {
        var r = el.getBoundingClientRect();
        s.position = 'absolute';
        s.left = (r.left + window.pageXOffset) + 'px';
        s.top = (r.top + window.pageYOffset) + 'px';
      }
      s.left = ((parseFloat(s.left) || 0) + dx) + 'px';
      s.top = ((parseFloat(s.top) || 0) + dy) + 'px';
    }
    function __where(name, axis) {
      var r = $(name).getBoundingClientRect();
      return Math.round(axis === 'x' ? r.left + window.pageXOffset : r.top + window.pageYOffset);
    }
    function __hit(a, b) {
      var p = $(a).getBoundingClientRect(), q = $(b).getBoundingClientRect();
      return p.left < q.right && p.right > q.left && p.top < q.bottom && p.bottom > q.top;
    }
    var __cx = 0, __cy = 0;
    var __fol = {}, __folOn = false, __moved = false;
    document.addEventListener('pointermove', function () { __moved = true; });
    document.addEventListener('pointerdown', function () { __moved = true; });
    function __folLoop() {
      for (var n in __fol) {
        var el = document.getElementById(n);
        if (!el) { delete __fol[n]; continue; }
        if (!__moved) continue;
        var s = el.style, tx = __cx - el.offsetWidth / 2, ty = __cy - el.offsetHeight / 2;
        if (s.position !== 'absolute') {
          var r = el.getBoundingClientRect();
          s.position = 'absolute';
          s.left = (r.left + window.pageXOffset) + 'px';
          s.top = (r.top + window.pageYOffset) + 'px';
        }
        var x = parseFloat(s.left) || 0, y = parseFloat(s.top) || 0, k = __fol[n] === 'soft' ? 0.15 : 1;
        s.left = (x + (tx - x) * k) + 'px';
        s.top = (y + (ty - y) * k) + 'px';
        s.pointerEvents = 'none';
      }
      requestAnimationFrame(__folLoop);
    }
    function __follow(name, mode) {
      if (mode === 'stop') {
        delete __fol[name];
        var e = document.getElementById(name);
        if (e) e.style.pointerEvents = '';
        return;
      }
      $(name);
      __fol[name] = mode;
      document.body.style.touchAction = 'none';
      if (!__folOn) { __folOn = true; __folLoop(); }
    }
    var __timers = [];

    var t;

    __timers.push(setInterval(function () {
      if (__where("foe", "x") < __cx) {
        __nudge("foe", 2, 0);
      } else {
        __nudge("foe", -2, 0);
      }
      if (__where("foe", "y") < __cy) {
        __nudge("foe", 0, 2);
      } else {
        __nudge("foe", 0, -2);
      }
      if (__hit("foe", "me")) {
        __timers.forEach(clearInterval);
        document.getElementById("hint").textContent = 'The zombie got you!';
      }
    }, 50));
    __timers.push(setInterval(function () {
      t = (typeof t === 'number' ? t : 0) + 1;
      document.getElementById("tm").textContent = 'Survived: ' + String(t);
    }, 1000));

    t = 0;
    __move("foe", 250, 300);
    __follow("me", "fast");
  </script>
</body>
</html>
