<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>뱀 게임</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #ecfccb; color: #1f2937; padding: 24px; }
    canvas { background: #f7fee7; border: 3px solid #4d7c0f; border-radius: 8px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>🐍 뱀 게임</h1>
  <p>점수: <span id="score">0</span></p>
  <canvas id="game" width="400" height="400"></canvas>
  <p id="msg">방향키로 뱀을 움직여 사과를 먹어요</p>
  <button id="start">시작</button>
  <script>
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const SIZE = 20;          // 칸 크기
    const COUNT = 20;         // 한 줄에 20칸
    const msg = document.getElementById('msg');
    const startBtn = document.getElementById('start');

    let snake = [];
    let dir = { x: 1, y: 0 };
    let nextDir = { x: 1, y: 0 };
    let food = { x: 15, y: 10 };
    let score = 0;
    let running = false;
    let timer = null;

    function placeFood() {
      do {
        food = { x: Math.floor(Math.random() * COUNT), y: Math.floor(Math.random() * COUNT) };
      } while (snake.some(function (s) { return s.x === food.x && s.y === food.y; }));
    }

    function startGame() {
      clearInterval(timer);
      snake = [{ x: 5, y: 10 }, { x: 4, y: 10 }, { x: 3, y: 10 }];
      dir = { x: 1, y: 0 };
      nextDir = { x: 1, y: 0 };
      score = 0;
      placeFood();
      running = true;
      document.getElementById('score').textContent = 0;
      msg.textContent = '';
      startBtn.textContent = '다시 시작';
      timer = setInterval(tick, 120);
      draw();
    }

    function gameOver() {
      running = false;
      clearInterval(timer);
      timer = null;
      msg.textContent = '💥 게임 오버! 점수: ' + score;
    }

    function tick() {
      if (!running) return;
      dir = nextDir;
      const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };
      // 벽이나 자기 몸에 부딪히면 끝
      const hitWall = head.x < 0 || head.x >= COUNT || head.y < 0 || head.y >= COUNT;
      const hitSelf = snake.some(function (s) { return s.x === head.x && s.y === head.y; });
      if (hitWall || hitSelf) {
        gameOver();
        return;
      }
      snake.unshift(head);
      if (head.x === food.x && head.y === food.y) {
        score += 1;
        document.getElementById('score').textContent = score;
        placeFood(); // 꼬리를 자르지 않아서 한 칸 길어져요
      } else {
        snake.pop();
      }
      draw();
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#dc2626';
      ctx.fillRect(food.x * SIZE + 2, food.y * SIZE + 2, SIZE - 4, SIZE - 4);
      snake.forEach(function (s, i) {
        ctx.fillStyle = i === 0 ? '#365314' : '#65a30d';
        ctx.fillRect(s.x * SIZE + 1, s.y * SIZE + 1, SIZE - 2, SIZE - 2);
      });
    }

    document.addEventListener('keydown', function (e) {
      if (e.key.startsWith('Arrow') || e.key === ' ') e.preventDefault();
      // 반대 방향으로는 바로 못 돌아요
      if (e.key === 'ArrowLeft' && dir.x !== 1) nextDir = { x: -1, y: 0 };
      if (e.key === 'ArrowRight' && dir.x !== -1) nextDir = { x: 1, y: 0 };
      if (e.key === 'ArrowUp' && dir.y !== 1) nextDir = { x: 0, y: -1 };
      if (e.key === 'ArrowDown' && dir.y !== -1) nextDir = { x: 0, y: 1 };
    });
    startBtn.addEventListener('click', startGame);
  </script>
</body>
</html>
