<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>반응속도 재기</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #f8fafc; color: #1f2937; padding: 24px; }
    #box { width: 320px; height: 200px; margin: 16px auto; border-radius: 16px; display: flex; align-items: center; justify-content: center;
      font-size: 26px; font-weight: bold; color: white; background: #3b82f6; cursor: pointer; user-select: none; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 22px; min-height: 28px; }
  </style>
</head>
<body>
  <h1>⚡ 반응속도 재기 (5번 평균)</h1>
  <div id="box">눌러서 시작</div>
  <p id="msg"></p>
  <p>기록: <span id="list">-</span></p>
  <button id="reset">처음부터</button>
  <script>
    const box = document.getElementById('box');
    const msg = document.getElementById('msg');
    let state = 'idle';   // idle(시작 전) → wait(빨강) → go(초록) → idle ...
    let times = [];
    let waitTimer = null;
    let goTime = 0;

    function setBox(color, text) {
      box.style.background = color;
      box.textContent = text;
    }

    function startRound() {
      state = 'wait';
      setBox('#dc2626', '초록색이 되면 클릭!');
      msg.textContent = '';
      // 1~3초 뒤에 초록색으로 바뀌어요
      waitTimer = setTimeout(showGreen, 1000 + Math.random() * 2000);
    }

    function showGreen() {
      state = 'go';
      goTime = performance.now();
      setBox('#16a34a', '지금 클릭!!');
    }

    box.addEventListener('click', function () {
      if (state === 'idle') {
        if (times.length >= 5) return; // 5번 끝나면 처음부터 버튼으로
        startRound();
      } else if (state === 'wait') {
        clearTimeout(waitTimer); // 너무 빨리 누르면 이번 판은 다시
        state = 'idle';
        setBox('#f59e0b', '너무 빨라요! 다시 클릭');
      } else if (state === 'go') {
        const ms = Math.round(performance.now() - goTime);
        times.push(ms);
        state = 'idle';
        document.getElementById('list').textContent = times.join('ms, ') + 'ms';
        if (times.length >= 5) {
          const avg = Math.round(times.reduce(function (a, b) { return a + b; }, 0) / times.length);
          setBox('#7c3aed', '평균 ' + avg + 'ms');
          msg.textContent = '🎉 끝! 평균 반응속도는 ' + avg + 'ms예요';
        } else {
          setBox('#3b82f6', ms + 'ms! 클릭해서 다음 (' + times.length + '/5)');
        }
      }
    });

    document.getElementById('reset').addEventListener('click', function () {
      clearTimeout(waitTimer);
      state = 'idle';
      times = [];
      document.getElementById('list').textContent = '-';
      msg.textContent = '';
      setBox('#3b82f6', '눌러서 시작');
    });
  </script>
</body>
</html>
