<body>
  <h2 id="title">French Flashcards</h2>
  <div id="card" class="box" style="background:#ffffff">
    <h1 id="front">chat</h1>
    <h3 id="back">cat</h3>
  </div>
  <div id="btns" class="box row">
    <button id="flip">Flip</button>
    <button id="next">Next</button>
    <button id="know">Got it ✅</button>
  </div>
  <p id="count">Learned: 0</p>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var w, i, got, m;

    document.getElementById("flip").addEventListener('click', function () {
      __show("back", "toggle");
    });
    document.getElementById("next").addEventListener('click', function () {
      i = i % w.length + 1;
      document.getElementById("front").textContent = w[(i - 1)];
      document.getElementById("back").textContent = m[(i - 1)];
      __show("back", "hide");
    });
    document.getElementById("know").addEventListener('click', function () {
      got = (typeof got === 'number' ? got : 0) + 1;
      document.getElementById("count").textContent = 'Learned: ' + String(got);
      i = i % w.length + 1;
      document.getElementById("front").textContent = w[(i - 1)];
      document.getElementById("back").textContent = m[(i - 1)];
      __show("back", "hide");
    });

    w = ['chat', 'pomme', 'école', 'livre'];
    m = ['cat', 'apple', 'school', 'book'];
    i = 1;
    got = 0;
    __show("back", "hide");
  </script>
