```html
<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>리듬 게임</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #0c0a09; color: #fafaf9; padding: 24px; }
    canvas { background: #1c1917; border: 3px solid #f472b6; border-radius: 8px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; color: #f9a8d4; min-height: 30px; }
  </style>
</head>
<body>
  <h1>🎵 리듬 게임 (D F J K)</h1>
  <p>점수: <span id="score">0</span> · 콤보: <span id="combo">0</span> · 목숨: <span id="lives">5</span></p>
  <canvas id="game" width="320" height="440"></canvas>
  <p id="msg">노트가 아래 선에 올 때 D F J K를 눌러요</p>
  <button id="start">시작</button>
  <script>
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    const LANES = ['d', 'f', 'j', 'k'];
    const LANE_W = W / 4;
    const HIT_Y = 380;      // 판정선
    const msg = document.getElementById('msg');
    let notes = [];         // { lane, y }
    let score = 0;
    let combo = 0;
    let lives = 5;
    let flash = [0, 0, 0, 0];
    let frame = 0;
    let running = false;
    let timer = null;

    function updateInfo() {
      document.getElementById('score').textContent = score;
      document.getElementById('combo').textContent = combo;
      document.getElementById('lives').textContent = lives;
    }

    function startGame() {
      clearInterval(timer);
      notes = [];
      score = 0;
      combo = 0;
      lives = 5;
      frame = 0;
      running = true;
      msg.textContent = '';
      document.getElementById('start').textContent = '다시 시작';
      updateInfo();
      timer = setInterval(tick, 20);
    }

    function gameOver() {
      running = false;
      clearInterval(timer);
      timer = null;
      msg.textContent = '💥 게임 오버! 점수: ' + score;
    }

    function miss() {
      combo = 0;
      lives = Math.max(0, lives - 1);
      updateInfo();
      if (lives === 0) gameOver();
    }

    function tick() {
      if (!running) return;
      frame += 1;
      if (frame % 30 === 0) notes.push({ lane: Math.floor(Math.random() * 4), y: -20 });
      for (let i = notes.length - 1; i >= 0; i--) {
        notes[i].y += 4;
        if (notes[i].y > HIT_Y + 40) {
          notes.splice(i, 1);   // 지나간 노트는 한 번만 미스
          miss();
          if (!running) return;
        }
      }
      flash = flash.map(function (f) { return Math.max(0, f - 1); });
      draw();
    }

    function press(lane) {
      if (!running) return;
      flash[lane] = 6;
      // 판정선 가까이(±30) 있는 그 줄의 노트 찾기
      let best = -1;
      notes.forEach(function (n, i) {
        if (n.lane === lane && Math.abs(n.y - HIT_Y) <= 30) {
          if (best === -1 || Math.abs(n.y - HIT_Y) < Math.abs(notes[best].y - HIT_Y)) best = i;
        }
      });
      if (best === -1) return; // 노트가 없으면 아무 일도 없어요
      const perfect = Math.abs(notes[best].y - HIT_Y) <= 12;
      notes.splice(best, 1);
      combo += 1;
      score += (perfect ? 100 : 50) + combo * 2;
      msg.textContent = perfect ? 'PERFECT!' : 'GOOD';
      updateInfo();
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      for (let l = 0; l < 4; l++) {
        ctx.fillStyle = flash[l] ? '#4c1d95' : (l % 2 ? '#292524' : '#1c1917');
        ctx.fillRect(l * LANE_W, 0, LANE_W, H);
        ctx.fillStyle = '#a8a29e';
        ctx.font = '18px sans-serif';
        ctx.fillText(LANES[l].toUpperCase(), l * LANE_W + LANE_W / 2 - 6, H - 15);
      }
      ctx.fillStyle = '#f472b6';
      ctx.fillRect(0, HIT_Y - 2, W, 4);
      ctx.fillStyle = '#38bdf8';
      notes.forEach(function (n) { ctx.fillRect(n.lane * LANE_W + 8, n.y - 8, LANE_W - 16, 16); });
    }

    document.addEventListener('keydown', function (e) {
      if (e.key.startsWith('Arrow') || e.key === ' ') e.preventDefault();
      if (e.repeat) return;
      const lane = LANES.indexOf(e.key.toLowerCase());
      if (lane !== -1) press(lane);
    });
    document.getElementById('start').addEventListener('click', startGame);
    draw();
  </script>
</body>
</html>
