<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>우주선 피하기</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #0f172a; color: #f8fafc; padding: 24px; }
    canvas { background: #020617; border: 3px solid #475569; border-radius: 8px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; color: #fbbf24; min-height: 30px; }
  </style>
</head>
<body>
  <h1>🚀 우주선 피하기</h1>
  <p>점수: <span id="score">0</span> · 목숨: <span id="lives">❤️❤️❤️</span></p>
  <canvas id="game" width="400" height="400"></canvas>
  <p id="msg">방향키로 운석을 피하세요!</p>
  <button id="start">시작</button>
  <script>
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    const msg = document.getElementById('msg');
    const startBtn = document.getElementById('start');

    let player = { x: 185, y: 350, w: 30, h: 30 };
    let rocks = [];
    let keys = {};
    let score = 0;
    let lives = 3;
    let invincible = 0; // 남은 무적 시간(틱)
    let running = false;
    let timer = null;

    function updateInfo() {
      document.getElementById('score').textContent = score;
      document.getElementById('lives').textContent = '❤️'.repeat(lives) || '없음';
    }

    function startGame() {
      clearInterval(timer);
      player.x = 185; player.y = 350;
      rocks = [];
      keys = {};
      score = 0;
      lives = 3;
      invincible = 0;
      running = true;
      msg.textContent = '';
      startBtn.textContent = '다시 시작';
      updateInfo();
      timer = setInterval(tick, 20);
    }

    function gameOver() {
      running = false;
      clearInterval(timer);
      timer = null;
      msg.textContent = '💥 게임 오버! 점수: ' + score;
      draw();
    }

    function hit() {
      lives = Math.max(0, lives - 1);
      invincible = 50; // 1초 동안 무적
      updateInfo();
      if (lives === 0) gameOver();
    }

    function tick() {
      if (!running) return;
      // 왼쪽/오른쪽은 x만, 위/아래는 y만 바꿔요
      if (keys.ArrowLeft) player.x = Math.max(0, player.x - 5);
      if (keys.ArrowRight) player.x = Math.min(W - player.w, player.x + 5);
      if (keys.ArrowUp) player.y = Math.max(0, player.y - 5);
      if (keys.ArrowDown) player.y = Math.min(H - player.h, player.y + 5);

      if (Math.random() < 0.04) {
        rocks.push({ x: Math.random() * W, y: -15, r: 15, speed: 2 + Math.random() * 3 });
      }
      for (const rock of rocks) rock.y += rock.speed;

      // 화면 밖으로 나간 운석은 피한 것 → 점수 +1
      for (let i = rocks.length - 1; i >= 0; i--) {
        if (rocks[i].y - rocks[i].r > H) {
          rocks.splice(i, 1);
          score += 1;
          updateInfo();
        }
      }

      // 운석 중심과 우주선 중심 사이 거리로 충돌 검사
      if (invincible > 0) {
        invincible -= 1;
      } else {
        const cx = player.x + player.w / 2, cy = player.y + player.h / 2;
        for (const rock of rocks) {
          if (Math.hypot(rock.x - cx, rock.y - cy) < rock.r + 13) {
            hit();
            break;
          }
        }
      }
      draw();
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      ctx.fillStyle = '#ef4444';
      for (const rock of rocks) {
        ctx.beginPath();
        ctx.arc(rock.x, rock.y, rock.r, 0, Math.PI * 2);
        ctx.fill();
      }
      // 무적일 때는 깜빡여요
      if (invincible % 10 < 5) {
        ctx.font = '28px sans-serif';
        ctx.textBaseline = 'top';
        ctx.fillText('🚀', player.x, player.y);
      }
    }

    document.addEventListener('keydown', function (e) {
      if (e.key.startsWith('Arrow') || e.key === ' ') e.preventDefault();
      keys[e.key] = true;
    });
    document.addEventListener('keyup', function (e) {
      keys[e.key] = false;
    });
    startBtn.addEventListener('click', startGame);
    draw();
  </script>
</body>
</html>
