<head>
  <meta charset="UTF-8">
  <title>소수 찾기</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #e0f2fe; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
  </style>
</head>
<body>
  <h2 id="title">소수 찾기</h2>
  <input id="n" type="number" placeholder="어디까지? (2~500)">
  <button id="go">찾기</button>
  <p id="count"></p>
  <p id="list"></p>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var c, k;

    function mathIsPrime(n) {
      // https://en.wikipedia.org/wiki/Primality_test#Naive_methods
      if (n == 2 || n == 3) {
        return true;
      }
      // False if n is NaN, negative, is 1, or not whole.
      // And false if n is divisible by 2 or 3.
      if (isNaN(n) || n <= 1 || n % 1 !== 0 || n % 2 === 0 || n % 3 === 0) {
        return false;
      }
      // Check all the numbers of form 6k +/- 1, up to sqrt(n).
      for (var x = 6; x <= Math.sqrt(n) + 1; x += 6) {
        if (n % (x - 1) === 0 || n % (x + 1) === 0) {
          return false;
        }
      }
      return true;
    }

    document.getElementById("go").addEventListener('click', function () {
      document.getElementById("list").textContent = '';
      c = 0;
      if ((parseFloat(document.getElementById("n").value) || 0) < 2 || (parseFloat(document.getElementById("n").value) || 0) > 500) {
        document.getElementById("count").textContent = '2에서 500 사이로 써 주세요';
      } else {
        var k_end = (parseFloat(document.getElementById("n").value) || 0);
        var k_inc = 1;
        if (2 > k_end) {
          k_inc = -k_inc;
        }
        for (k = 2; k_inc >= 0 ? k <= k_end : k >= k_end; k += k_inc) {
          if (mathIsPrime(k)) {
            c = (typeof c === 'number' ? c : 0) + 1;
            __add("list", String(k) + ' ');
          }
        }
        document.getElementById("count").textContent = '소수 개수: ' + String(c);
      }
    });
  </script>
</body>
</html>
