<head>
  <meta charset="UTF-8">
  <title>Dodge!</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #0f172a; color: #f1f5f9; text-align: center; }
    canvas { max-width: 100%; background: #ffffff; border: 1px solid #d1d5db; border-radius: 8px; touch-action: manipulation; }
  </style>
</head>
<body>
  <h2 id="score">0</h2>
  <canvas id="game" width="300" height="300"></canvas>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    var __timers = [];
    function __pen(name) { return $(name).getContext('2d'); }
    function __clear(name) { var c = $(name); __pen(name).clearRect(0, 0, c.width, c.height); }
    function __rect(name, x, y, w, h, color) { var g = __pen(name); g.fillStyle = color; g.fillRect(x, y, w, h); }

    var px, ex, ey, pts, sp;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowLeft") {
        e.preventDefault();
        px = (typeof px === 'number' ? px : 0) + -20;
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowRight") {
        e.preventDefault();
        px = (typeof px === 'number' ? px : 0) + 20;
      }
    });
    __timers.push(setInterval(function () {
      __clear("game");
      __rect("game", px, 270, 30, 20, "#3b82f6");
      __rect("game", ex, ey, 30, 30, "#ef4444");
      ey = (typeof ey === 'number' ? ey : 0) + sp;
      if (ey > 240) {
        if (Math.abs(ex - px) < 30) {
          __timers.forEach(clearInterval);
          alert('Game over! Reload to play again');
        } else {
          ey = 0;
          ex = mathRandomInt(0, 270);
          pts = (typeof pts === 'number' ? pts : 0) + 1;
          document.getElementById("score").textContent = pts;
          sp = (typeof sp === 'number' ? sp : 0) + 0.5;
        }
      }
    }, 30));

    px = 135;
    ex = 40;
    ey = 0;
    pts = 0;
    sp = 4;
  </script>
</body>
</html>
