<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>시계</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #0f172a; color: #f1f5f9; text-align: center; }
  </style>
</head>
<body>
  <h1 id="now"></h1>
  <h2 id="hello"></h2>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __size(name, prop, v) {
      var s = $(name).style;
      if (prop === 'opacity') s.opacity = v / 100;
      else if (prop === 'rotate') s.transform = 'rotate(' + v + 'deg)';
      else s[prop] = v + 'px';
    }
    var __timers = [];
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    __timers.push(setInterval(function () {
      document.getElementById("now").textContent = [new Date().getHours(),':',new Date().getMinutes(),':',new Date().getSeconds()].join('');
      if (new Date().getHours() < 12) {
        document.getElementById("hello").textContent = '좋은 아침이에요!';
      } else {
        document.getElementById("hello").textContent = '좋은 오후예요!';
      }
      if (new Date().getMinutes() == 0 && new Date().getSeconds() == 0) {
        __beep(523.25, 1);
      }
    }, 1000));

    __size("now", "fontSize", 64);
    document.getElementById("now").style.color = "#ffffff";
    document.getElementById("hello").style.color = "#ffc93c";
  </script>
</body>
</html>
