  <p id="stats">Heads 0 · Tails 0</p>
  <script>
    var h, t;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("flip").addEventListener('click', function () {
      if (mathRandomInt(1, 2) == 1) {
        h = (typeof h === 'number' ? h : 0) + 1;
        document.getElementById("side").textContent = 'Heads 🙂';
      } else {
        t = (typeof t === 'number' ? t : 0) + 1;
        document.getElementById("side").textContent = 'Tails 🦅';
      }
      document.getElementById("stats").textContent = ['Heads ',h,' · Tails ',t].join('');
    });

    h = 0;
    t = 0;
  </script>
</body>
