  <script>
    function mathIsPrime(n) {
      // https://en.wikipedia.org/wiki/Primality_test#Naive_methods
      if (n == 2 || n == 3) {
        return true;
      }
      // False if n is NaN, negative, is 1, or not whole.
      // And false if n is divisible by 2 or 3.
      if (isNaN(n) || n <= 1 || n % 1 !== 0 || n % 2 === 0 || n % 3 === 0) {
        return false;
      }
      // Check all the numbers of form 6k +/- 1, up to sqrt(n).
      for (var x = 6; x <= Math.sqrt(n) + 1; x += 6) {
        if (n % (x - 1) === 0 || n % (x + 1) === 0) {
          return false;
        }
      }
      return true;
    }

    document.getElementById("checkBtn").addEventListener('click', function () {
      if (mathIsPrime((parseFloat(document.getElementById("numBox").value) || 0))) {
        document.getElementById("result").textContent = [(parseFloat(document.getElementById("numBox").value) || 0),'는 ','소수예요! ✨'].join('');
        document.getElementById("result").style.color = "#22c55e";
      } else {
        document.getElementById("result").textContent = [(parseFloat(document.getElementById("numBox").value) || 0),'는 ','소수가 아니에요'].join('');
        document.getElementById("result").style.color = "#ef4444";
