    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #0f172a; color: #f1f5f9; text-align: center; }
    canvas { max-width: 100%; background: #ffffff; border: 1px solid #d1d5db; border-radius: 8px; touch-action: manipulation; }
  </style>
</head>
<body>
  <h2 id="제목1">별 잡기</h2>
  <canvas id="그림판1" width="320" height="220"></canvas>
  <p id="점수판">점수: 0</p>
  <p id="남은시간">남은 시간: 20</p>
  <p id="최고기록"></p>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    var __mx = 0, __my = 0;
    function __pos(e, el) {
      var r = el.getBoundingClientRect();
      __mx = Math.round((e.clientX - r.left) * (el.width ? el.width / r.width : 1));
      __my = Math.round((e.clientY - r.top) * (el.height ? el.height / r.height : 1));
    }
    var __mem = {};
    function __save(k, v) {
      k = 'ffb:' + k;
      __mem[k] = v;
      try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {}
    }
    function __load(k, d) {
      k = 'ffb:' + k;
      try {
        var s = localStorage.getItem(k);
        if (s !== null) return JSON.parse(s);
      } catch (e) {}
      return k in __mem ? __mem[k] : d;
    }
    function __dist(x1, y1, x2, y2) { return Math.hypot(x2 - x1, y2 - y1); }
    var __timers = [];
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }
    function __pen(name) { return $(name).getContext('2d'); }
    function __clear(name) { var c = $(name); __pen(name).clearRect(0, 0, c.width, c.height); }
    function __circle(name, x, y, r, color) { var g = __pen(name); g.fillStyle = color; g.beginPath(); g.arc(x, y, Math.max(0, r), 0, Math.PI * 2); g.fill(); }

    var x, left, y, score, sx, sy;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowLeft") {
        e.preventDefault();
        x = (typeof x === 'number' ? x : 0) + -10;
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowRight") {
        e.preventDefault();
        x = (typeof x === 'number' ? x : 0) + 10;
      }
    });
