  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var names, pool, turn, who;

    function listsGetSortCompare(type, direction) {
      var compareFuncs = {
        'NUMERIC': function(a, b) {
            return Number(a) - Number(b); },
        'TEXT': function(a, b) {
            return String(a) > String(b) ? 1 : -1; },
        'IGNORE_CASE': function(a, b) {
            return String(a).toLowerCase() > String(b).toLowerCase() ? 1 : -1; },
      };
      var compare = compareFuncs[type];
      return function(a, b) { return compare(a, b) * direction; };
    }

    function listsGetRandomItem(list, remove) {
      var x = Math.floor(Math.random() * list.length);
      if (remove) {
        return list.splice(x, 1)[0];
      } else {
        return list[x];
      }
    }

    document.getElementById("addBtn").addEventListener('click', function () {
      if (!!document.getElementById("nameBox").value.trim().length) {
        names.push(document.getElementById("nameBox").value.trim());
        __add("people", String(document.getElementById("nameBox").value.trim()) + ' ');
        document.getElementById("nameBox").value = '';
      }
    });
    document.getElementById("go").addEventListener('click', function () {
      document.getElementById("listA").textContent = '';
      document.getElementById("listB").textContent = '';
      pool = names.slice().sort(listsGetSortCompare("TEXT", 1));
      turn = 0;
      while (!!pool.length) {
        who = listsGetRandomItem(pool, true);
        if (turn % 2 == 0) {
          __add("listA", who);
        } else {
          __add("listB", who);
        }
        turn = (typeof turn === 'number' ? turn : 0) + 1;
      }
    });

    names = [];
  </script>
