<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>미로 탈출</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #f5f5f4; color: #1f2937; padding: 24px; }
    canvas { border: 3px solid #44403c; border-radius: 4px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>🧩 미로 탈출</h1>
  <p>방향키로 🐭를 움직여 🧀까지 가세요! · 시간: <span id="time">0</span>초 · 걸음: <span id="steps">0</span></p>
  <canvas id="game" width="440" height="440"></canvas>
  <p id="msg"></p>
  <button id="restart">다시 시작</button>
  <script>
    // # 벽, . 길, S 출발, G 도착
    const maze = [
      '###########',
      '#S..#.....#',
      '#.#.#.###.#',
      '#.#...#...#',
      '#.#####.###',
      '#...#...#.#',
      '###.#.###.#',
      '#...#.....#',
      '#.#####.#.#',
      '#.......#G#',
      '###########'
    ];
    const SIZE = 40;
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const msg = document.getElementById('msg');
    let player = { x: 1, y: 1 };
    let goal = { x: 9, y: 9 };
    let steps = 0;
    let seconds = 0;
    let running = false;
    let timer = null;

    function isWall(x, y) {
      return maze[y][x] === '#';
    }

    function startGame() {
      clearInterval(timer);
      player = { x: 1, y: 1 };
      steps = 0;
      seconds = 0;
      running = true;
      msg.textContent = '';
      document.getElementById('time').textContent = 0;
      document.getElementById('steps').textContent = 0;
      timer = setInterval(function () {
        if (!running) return;
        seconds += 1;
        document.getElementById('time').textContent = seconds;
      }, 1000);
      draw();
    }

    function move(dx, dy) {
      if (!running) return;
      const nx = player.x + dx;
      const ny = player.y + dy;
      if (isWall(nx, ny)) return; // 벽이면 못 가요
      player.x = nx;
      player.y = ny;
      steps += 1;
      document.getElementById('steps').textContent = steps;
      if (player.x === goal.x && player.y === goal.y) {
        running = false;
        clearInterval(timer);
        msg.textContent = '🎉 탈출 성공! ' + seconds + '초, ' + steps + '걸음';
      }
      draw();
    }

    function draw() {
      for (let y = 0; y < maze.length; y++) {
        for (let x = 0; x < maze[y].length; x++) {
          ctx.fillStyle = isWall(x, y) ? '#44403c' : '#fafaf9';
          ctx.fillRect(x * SIZE, y * SIZE, SIZE, SIZE);
        }
      }
      ctx.font = '30px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('🧀', goal.x * SIZE + SIZE / 2, goal.y * SIZE + SIZE / 2);
      ctx.fillText('🐭', player.x * SIZE + SIZE / 2, player.y * SIZE + SIZE / 2);
    }

    document.addEventListener('keydown', function (e) {
      if (e.key.startsWith('Arrow') || e.key === ' ') e.preventDefault();
      if (e.key === 'ArrowLeft') move(-1, 0);
      if (e.key === 'ArrowRight') move(1, 0);
      if (e.key === 'ArrowUp') move(0, -1);
      if (e.key === 'ArrowDown') move(0, 1);
    });
    document.getElementById('restart').addEventListener('click', startGame);
    startGame();
  </script>
</body>
</html>
