  <h3 id="numText">Question 1/10</h3>
  <h1 id="qText"></h1>
  <div id="row1" class="box row">
    <input id="ansBox" type="number" placeholder="Answer">
    <button id="checkBtn">Check</button>
  </div>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var a, i, b, score;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function ask() {
      a = mathRandomInt(2, 9);
      b = mathRandomInt(2, 9);
      document.getElementById("qText").textContent = [a,' × ',b].join('');
      document.getElementById("numText").textContent = ['Question ',i,'/10'].join('');
      document.getElementById("ansBox").value = '';
    }

    // 이 함수를 설명하세요...
    function check() {
      if ((parseFloat(document.getElementById("ansBox").value) || 0) == a * b) {
        score = (typeof score === 'number' ? score : 0) + 1;
      }
      i = (typeof i === 'number' ? i : 0) + 1;
      if (i > 10) {
        document.getElementById("qText").textContent = ['Score: ',score,'/10'].join('');
        __show("row1", "hide");
        __show("numText", "hide");
      } else {
        ask();
      }
    }

    document.getElementById("checkBtn").addEventListener('click', function () {
      check();
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "Enter") {
        e.preventDefault();
        if (i <= 10) {
          check();
        }
      }
    });

    i = 1;
    score = 0;
    ask();
  </script>
</body>
