<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>다른 색 찾기</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #fafafa; color: #1f2937; padding: 24px; }
    #grid { display: grid; gap: 4px; width: 320px; height: 320px; margin: 16px auto; }
    .tile { border: none; border-radius: 6px; cursor: pointer; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>👀 다른 색 찾기</h1>
  <p>점수: <span id="score">0</span> · 남은 시간: <span id="time">30</span>초</p>
  <div id="grid"></div>
  <p id="msg">색이 살짝 다른 칸 하나를 찾아 클릭! 틀리면 3초 깎여요</p>
  <button id="start">시작</button>
  <script>
    const grid = document.getElementById('grid');
    const msg = document.getElementById('msg');
    let size = 2;        // 한 줄에 칸 수
    let answer = 0;      // 다른 색 칸 번호
    let score = 0;
    let timeLeft = 30;
    let running = false;
    let timer = null;

    function newRound() {
      size = Math.min(8, 2 + Math.floor(score / 3));     // 점수가 오를수록 칸이 많아지고
      const diff = Math.max(6, 30 - score * 1.5);          // 색 차이는 작아져요
      const hue = Math.floor(Math.random() * 360);
      answer = Math.floor(Math.random() * size * size);
      grid.innerHTML = '';
      grid.style.gridTemplateColumns = 'repeat(' + size + ', 1fr)';
      for (let i = 0; i < size * size; i++) {
        const tile = document.createElement('button');
        tile.className = 'tile';
        tile.style.background = 'hsl(' + hue + ', 70%, ' + (i === answer ? 50 + diff / 2 : 50) + '%)';
        tile.addEventListener('click', function () { pick(i); });
        grid.appendChild(tile);
      }
    }

    function pick(i) {
      if (!running) return;
      if (i === answer) {
        score += 1;
        document.getElementById('score').textContent = score;
        newRound();
      } else {
        timeLeft = Math.max(0, timeLeft - 3);
        document.getElementById('time').textContent = timeLeft;
        if (timeLeft === 0) endGame();
      }
    }

    function startGame() {
      clearInterval(timer);
      score = 0;
      timeLeft = 30;
      running = true;
      msg.textContent = '';
      document.getElementById('score').textContent = 0;
      document.getElementById('time').textContent = 30;
      document.getElementById('start').textContent = '다시 시작';
      newRound();
      timer = setInterval(function () {
        if (!running) return;
        timeLeft = Math.max(0, timeLeft - 1);
        document.getElementById('time').textContent = timeLeft;
        if (timeLeft === 0) endGame();
      }, 1000);
    }

    function endGame() {
      running = false;
      clearInterval(timer);
      timer = null;
      grid.querySelectorAll('.tile').forEach(function (t, i) {
        t.disabled = true;
        if (i === answer) t.textContent = '⭐';
      });
      msg.textContent = '⏰ 게임 끝! 점수: ' + score;
    }

    document.getElementById('start').addEventListener('click', startGame);
  </script>
</body>
</html>
