  <title>막대 시계</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #0f172a; color: #f1f5f9; text-align: center; }
    canvas { max-width: 100%; background: #ffffff; border: 1px solid #d1d5db; border-radius: 8px; touch-action: manipulation; }
  </style>
</head>
<body>
  <canvas id="clock" width="300" height="160"></canvas>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    var __timers = [];
    function __pen(name) { return $(name).getContext('2d'); }
    function __clear(name) { var c = $(name); __pen(name).clearRect(0, 0, c.width, c.height); }
    function __rect(name, x, y, w, h, color) { var g = __pen(name); g.fillStyle = color; g.fillRect(x, y, w, h); }
    function __text(name, text, x, y, color) { var g = __pen(name); g.fillStyle = color; g.font = '20px sans-serif'; g.fillText(text, x, y); }

    // 이 함수를 설명하세요...
    function tick() {
      __clear("clock");
      __rect("clock", 0, 0, 300, 160, "#111111");
      __text("clock", [new Date().getHours(),':',new Date().getMinutes(),':',new Date().getSeconds()].join(''), 20, 40, "#ffffff");
      __rect("clock", 20, 60, new Date().getHours() * 10, 18, "#ef4444");
      __rect("clock", 20, 90, new Date().getMinutes() * 4, 18, "#facc15");
      __rect("clock", 20, 120, new Date().getSeconds() * 4, 18, "#38bdf8");
    }

    __timers.push(setInterval(function () {
      tick();
    }, 1000));

    tick();
  </script>
</body>
</html>
