  <h1 id="title">풍선 불기</h1>
  <h1 id="ball">🎈</h1>
  <button id="pumpBtn">바람 넣기 💨</button>
  <h2 id="result"></h2>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __size(name, prop, v) {
      var s = $(name).style;
      if (prop === 'opacity') s.opacity = v / 100;
      else if (prop === 'rotate') s.transform = 'rotate(' + v + 'deg)';
      else s[prop] = v + 'px';
    }

    var air, limit;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function newBalloon() {
      air = 0;
      limit = mathRandomInt(4, 12);
      __size("ball", "fontSize", 40);
      document.getElementById("ball").textContent = '🎈';
      document.getElementById("result").textContent = '';
    }

    document.getElementById("pumpBtn").addEventListener('click', function () {
      if (air < limit) {
        air = (typeof air === 'number' ? air : 0) + 1;
        __size("ball", "fontSize", 40 + air * 12);
        if (air >= limit) {
          document.getElementById("ball").textContent = '💥';
          document.getElementById("result").textContent = '펑! 💥 터졌어요';
        }
      }
    });

    newBalloon();
  </script>
</body>
</html>
