        left -= 1;
        timeEl.textContent = left;
        if (left <= 0) {
          clearInterval(timer);
          timer = null;
          timeEl.textContent = '끝! ⏰';
        }
      }, 1000);
    });
    document.getElementById('reset').addEventListener('click', function () {
      clearInterval(timer);
      timer = null;
      left = 180;
      timeEl.textContent = left;
    });
  </script>
</body>
