<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>틱택토</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #eff6ff; color: #1f2937; padding: 24px; }
    #board { display: grid; grid-template-columns: repeat(3, 90px); gap: 6px; justify-content: center; margin: 16px auto; }
    .cell { width: 90px; height: 90px; font-size: 48px; border: none; border-radius: 10px; background: white; cursor: pointer; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>⭕❌ 틱택토 (나 ❌ vs 컴퓨터 ⭕)</h1>
  <div id="board"></div>
  <p id="msg">빈칸을 눌러 ❌를 놓으세요</p>
  <p>나 <span id="win">0</span>승 · 컴퓨터 <span id="lose">0</span>승 · 무승부 <span id="draw">0</span></p>
  <button id="restart">새 판</button>
  <script>
    const LINES = [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]];
    const msg = document.getElementById('msg');
    const cellEls = [];
    let board = Array(9).fill('');
    let running = true;
    let record = { win: 0, lose: 0, draw: 0 };

    for (let i = 0; i < 9; i++) {
      const b = document.createElement('button');
      b.className = 'cell';
      b.addEventListener('click', function () { playerMove(i); });
      document.getElementById('board').appendChild(b);
      cellEls.push(b);
    }

    function winner(mark) {
      return LINES.some(function (l) { return l.every(function (i) { return board[i] === mark; }); });
    }

    // 이길 수 있는 칸 → 막아야 하는 칸 → 가운데 → 아무 빈칸
    function findSpot(mark) {
      for (const l of LINES) {
        const marks = l.map(function (i) { return board[i]; });
        if (marks.filter(function (m) { return m === mark; }).length === 2 && marks.includes('')) {
          return l[marks.indexOf('')];
        }
      }
      return -1;
    }

    function computerMove() {
      let spot = findSpot('⭕');
      if (spot === -1) spot = findSpot('❌');
      if (spot === -1 && board[4] === '') spot = 4;
      if (spot === -1) {
        const empty = [];
        board.forEach(function (v, i) { if (v === '') empty.push(i); });
        spot = empty[Math.floor(Math.random() * empty.length)];
      }
      board[spot] = '⭕';
    }

    function check() {
      let result = '';
      if (winner('❌')) { result = '🎉 내가 이겼어요!'; record.win += 1; }
      else if (winner('⭕')) { result = '💥 게임 오버! 컴퓨터가 이겼어요'; record.lose += 1; }
      else if (!board.includes('')) { result = '🤝 무승부!'; record.draw += 1; }
      if (result) {
        running = false;
        msg.textContent = result;
        document.getElementById('win').textContent = record.win;
        document.getElementById('lose').textContent = record.lose;
        document.getElementById('draw').textContent = record.draw;
      }
      return result !== '';
    }

    function draw() {
      board.forEach(function (v, i) { cellEls[i].textContent = v; });
    }

    function playerMove(i) {
      if (!running || board[i] !== '') return;
      board[i] = '❌';
      if (!check()) {
        computerMove();
        check();
      }
      draw();
    }

    document.getElementById('restart').addEventListener('click', function () {
      board = Array(9).fill('');
      running = true;
      msg.textContent = '빈칸을 눌러 ❌를 놓으세요';
      draw();
    });
  </script>
</body>
</html>
