<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>슈팅 게임</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #111827; color: #f9fafb; padding: 24px; }
    canvas { background: #030712; border: 3px solid #6366f1; border-radius: 8px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; color: #facc15; min-height: 30px; }
  </style>
</head>
<body>
  <h1>🔫 슈팅 게임</h1>
  <p>점수: <span id="score">0</span> · 목숨: <span id="lives">3</span></p>
  <canvas id="game" width="400" height="450"></canvas>
  <p id="msg">← → 이동, 스페이스바 발사</p>
  <button id="start">시작</button>
  <script>
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    const msg = document.getElementById('msg');
    const startBtn = document.getElementById('start');

    let player = { x: 182, y: 410, w: 36, h: 24 };
    let bullets = [];
    let enemies = [];
    let keys = {};
    let score = 0;
    let lives = 3;
    let cooldown = 0;    // 총알 사이 쉬는 시간
    let safeTime = 0;
    let running = false;
    let timer = null;

    function overlap(a, b) {
      return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
    }

    function updateInfo() {
      document.getElementById('score').textContent = score;
      document.getElementById('lives').textContent = lives;
    }

    function startGame() {
      clearInterval(timer);
      player.x = 182;
      bullets = [];
      enemies = [];
      keys = {};
      score = 0;
      lives = 3;
      cooldown = 0;
      safeTime = 0;
      running = true;
      msg.textContent = '';
      startBtn.textContent = '다시 시작';
      updateInfo();
      timer = setInterval(tick, 20);
    }

    function gameOver() {
      running = false;
      clearInterval(timer);
      timer = null;
      msg.textContent = '💥 게임 오버! 점수: ' + score;
    }

    function loseLife() {
      lives = Math.max(0, lives - 1);
      safeTime = 50;
      updateInfo();
      if (lives === 0) gameOver();
    }

    function tick() {
      if (!running) return;
      if (keys.ArrowLeft) player.x = Math.max(0, player.x - 6);
      if (keys.ArrowRight) player.x = Math.min(W - player.w, player.x + 6);
      if (cooldown > 0) cooldown -= 1;
      if (keys[' '] && cooldown === 0) {
        bullets.push({ x: player.x + player.w / 2 - 2, y: player.y - 10, w: 4, h: 10 });
        cooldown = 12;
      }
      if (Math.random() < 0.025) {
        enemies.push({ x: Math.random() * (W - 30), y: -30, w: 30, h: 24, speed: 1.5 + Math.random() * 1.5 });
      }

      bullets.forEach(function (b) { b.y -= 8; });
      bullets = bullets.filter(function (b) { return b.y + b.h > 0; });
      enemies.forEach(function (e) { e.y += e.speed; });

      // 총알과 적이 겹치면 둘 다 없어지고 점수 +10
      for (let i = enemies.length - 1; i >= 0; i--) {
        for (let j = bullets.length - 1; j >= 0; j--) {
          if (overlap(enemies[i], bullets[j])) {
            enemies.splice(i, 1);
            bullets.splice(j, 1);
            score += 10;
            updateInfo();
            break;
          }
        }
      }

      if (safeTime > 0) safeTime -= 1;
      for (let i = enemies.length - 1; i >= 0; i--) {
        const e = enemies[i];
        if (e.y > H) {
          enemies.splice(i, 1);       // 놓친 적은 목숨 -1
          loseLife();
        } else if (safeTime === 0 && overlap(e, player)) {
          enemies.splice(i, 1);       // 부딪힌 적도 없어져요
          loseLife();
        }
        if (!running) return;
      }
      draw();
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      ctx.fillStyle = '#facc15';
      bullets.forEach(function (b) { ctx.fillRect(b.x, b.y, b.w, b.h); });
      ctx.font = '24px sans-serif';
      ctx.textBaseline = 'top';
      enemies.forEach(function (e) { ctx.fillText('👾', e.x, e.y); });
      if (safeTime % 10 < 5) {
        ctx.fillStyle = '#38bdf8';
        ctx.beginPath();
        ctx.moveTo(player.x + player.w / 2, player.y);
        ctx.lineTo(player.x + player.w, player.y + player.h);
        ctx.lineTo(player.x, player.y + player.h);
        ctx.fill();
      }
    }

    document.addEventListener('keydown', function (e) {
      if (e.key.startsWith('Arrow') || e.key === ' ') e.preventDefault();
      keys[e.key] = true;
    });
    document.addEventListener('keyup', function (e) {
      keys[e.key] = false;
    });
    startBtn.addEventListener('click', startGame);
  </script>
</body>
</html>
