<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>곰돌이 산책</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #fff8e1; color: #1f2937; text-align: center; }
  </style>
</head>
<body>
  <h2 id="title">곰돌이 산책</h2>
  <p id="hint">화살표 키를 눌러요</p>
  <h1 id="hero">🐻</h1>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __move(name, x, y) {
      var s = $(name).style;
      s.position = 'absolute';
      s.left = x + 'px';
      s.top = y + 'px';
    }
    function __nudge(name, dx, dy) {
      var el = $(name), s = el.style;
      if (s.position !== 'absolute') {
        var r = el.getBoundingClientRect();
        s.position = 'absolute';
        s.left = (r.left + window.pageXOffset) + 'px';
        s.top = (r.top + window.pageYOffset) + 'px';
      }
      s.left = ((parseFloat(s.left) || 0) + dx) + 'px';
      s.top = ((parseFloat(s.top) || 0) + dy) + 'px';
    }
    function __stay(name) {
      var el = $(name), s = el.style, d = document.documentElement;
      if (s.position !== 'absolute') return;
      var x = Math.max(0, Math.min(parseFloat(s.left) || 0, d.clientWidth - el.offsetWidth));
      var y = Math.max(0, Math.min(parseFloat(s.top) || 0, d.clientHeight - el.offsetHeight));
      s.left = x + 'px';
      s.top = y + 'px';
    }

    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowLeft") {
        e.preventDefault();
        __nudge("hero", -8, 0);
        __stay("hero");
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowRight") {
        e.preventDefault();
        __nudge("hero", 8, 0);
        __stay("hero");
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowUp") {
        e.preventDefault();
        __nudge("hero", 0, -8);
        __stay("hero");
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowDown") {
        e.preventDefault();
        __nudge("hero", 0, 8);
        __stay("hero");
      }
    });

    __move("hero", 150, 200);
  </script>
