  <style>
    body { font-family: sans-serif; text-align: center; background: #fefce8; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    .choice { display: block; width: 260px; margin: 8px auto; border-radius: 10px; border: 2px solid #ca8a04; background: white; }
    #question { font-size: 24px; font-weight: bold; min-height: 32px; }
    #feedback { font-size: 20px; min-height: 26px; }
  </style>
</head>
<body>
  <h1>🧠 상식 퀴즈 5문제</h1>
  <p>문제 <span id="num">1</span>/5 · 점수: <span id="score">0</span></p>
  <p id="question"></p>
  <div id="choices"></div>
  <p id="feedback"></p>
  <button id="restart">다시 풀기</button>
  <script>
    const questions = [
      { q: '무지개는 몇 가지 색일까요?', options: ['5가지', '6가지', '7가지', '8가지'], answer: 2 },
      { q: '우리나라의 수도는?', options: ['부산', '서울', '대구', '인천'], answer: 1 },
      { q: '거미의 다리는 몇 개?', options: ['6개', '8개', '10개', '4개'], answer: 1 },
      { q: '물이 어는 온도는 몇 도?', options: ['0도', '10도', '100도', '-10도'], answer: 0 },
      { q: '태양계에서 가장 큰 행성은?', options: ['지구', '화성', '토성', '목성'], answer: 3 }
    ];
    let current = 0;
    let score = 0;
    let answered = false; // 한 문제에 한 번만 답할 수 있어요
    let nextTimer = null;
    const choicesEl = document.getElementById('choices');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      const item = questions[current];
      answered = false;
      document.getElementById('num').textContent = current + 1;
      document.getElementById('question').textContent = item.q;
      feedback.textContent = '';
      choicesEl.innerHTML = '';
      item.options.forEach(function (text, i) {
        const b = document.createElement('button');
        b.className = 'choice';
        b.textContent = text;
        b.addEventListener('click', function () { choose(i); });
        choicesEl.appendChild(b);
      });
    }

    function choose(i) {
      if (answered) return;
      answered = true;
      const item = questions[current];
      if (i === item.answer) {
        score += 1;
        feedback.textContent = '⭕ 정답!';
      } else {
        feedback.textContent = '❌ 땡! 정답은 ' + item.options[item.answer];
      }
      document.getElementById('score').textContent = score;
      nextTimer = setTimeout(next, 800);
    }

    function next() {
      current += 1;
      if (current < questions.length) {
        showQuestion();
      } else {
        document.getElementById('question').textContent = '끝! 5문제 중 ' + score + '문제 맞혔어요 ' + (score === 5 ? '🏆' : '👍');
        choicesEl.innerHTML = '';
        feedback.textContent = '';
      }
    }

    document.getElementById('restart').addEventListener('click', function () {
      clearTimeout(nextTimer); // 넘어가는 중이던 것도 취소
      current = 0;
      score = 0;
      document.getElementById('score').textContent = 0;
      showQuestion();
    });
    showQuestion();
  </script>
</body>
</html>
