<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>그림판</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #f5f3ff; color: #1f2937; padding: 24px; }
    canvas { background: white; border: 2px solid #8b5cf6; border-radius: 8px; cursor: crosshair; touch-action: none; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    input { font-size: 18px; margin: 4px; vertical-align: middle; }
    .on { background: #8b5cf6; color: white; }
  </style>
</head>
<body>
  <h1>🎨 그림판</h1>
  <div>
    색: <input id="color" type="color" value="#1d4ed8">
    굵기: <input id="size" type="range" min="1" max="30" value="6">
    <button id="pen" class="on">✏️ 펜</button>
    <button id="eraser">🧽 지우개</button>
    <button id="clear">🗑️ 전부 지우기</button>
  </div>
  <canvas id="board" width="500" height="350"></canvas>
  <script>
    const canvas = document.getElementById('board');
    const ctx = canvas.getContext('2d');
    const penBtn = document.getElementById('pen');
    const eraserBtn = document.getElementById('eraser');
    let drawing = false;
    let erasing = false;
    let lastX = 0, lastY = 0;

    function clearBoard() {
      ctx.fillStyle = 'white';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }

    function pos(e) {
      const rect = canvas.getBoundingClientRect();
      return { x: e.clientX - rect.left, y: e.clientY - rect.top };
    }

    canvas.addEventListener('mousedown', function (e) {
      drawing = true;
      const p = pos(e);
      lastX = p.x;
      lastY = p.y;
    });

    canvas.addEventListener('mousemove', function (e) {
      if (!drawing) return;
      const p = pos(e);
      ctx.strokeStyle = erasing ? 'white' : document.getElementById('color').value;
      ctx.lineWidth = Number(document.getElementById('size').value) * (erasing ? 3 : 1);
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(lastX, lastY);
      ctx.lineTo(p.x, p.y);
      ctx.stroke();
      lastX = p.x;
      lastY = p.y;
    });

    // 캔버스 밖에서 손을 떼도 멈추도록 window에서 받아요
    window.addEventListener('mouseup', function () { drawing = false; });

    penBtn.addEventListener('click', function () {
      erasing = false;
      penBtn.classList.add('on');
      eraserBtn.classList.remove('on');
    });
    eraserBtn.addEventListener('click', function () {
      erasing = true;
      eraserBtn.classList.add('on');
      penBtn.classList.remove('on');
    });
    document.getElementById('clear').addEventListener('click', clearBoard);
    clearBoard();
  </script>
</body>
</html>
