    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var n, k;

    document.getElementById("findBtn").addEventListener('click', function () {
      n = (parseFloat(document.getElementById("nBox").value) || 0);
      document.getElementById("numList").textContent = '';
      document.getElementById("label").textContent = String(n) + '의 약수: ';
      if (n > 0) {
        var k_inc = 1;
        if (1 > n) {
          k_inc = -k_inc;
        }
        for (k = 1; k_inc >= 0 ? k <= n : k >= n; k += k_inc) {
          if (n % k == 0) {
            __add("numList", k);
          }
        }
      }
    });
  </script>
