      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var me, w, com, l, played, d;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function play(me) {
      if (played < 5) {
        com = mathRandomInt(1, 3);
        played = (typeof played === 'number' ? played : 0) + 1;
        d = ((me - com) + 3) % 3;
        if (d == 1) {
          w = (typeof w === 'number' ? w : 0) + 1;
          document.getElementById("result").textContent = '이겼다!';
        } else if (d == 2) {
          l = (typeof l === 'number' ? l : 0) + 1;
          document.getElementById("result").textContent = '졌다...';
