<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>벽돌깨기</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #ecfeff; color: #1f2937; padding: 24px; }
    canvas { background: #1e293b; border-radius: 8px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>🧱 벽돌깨기</h1>
  <p>점수: <span id="score">0</span> · 목숨: <span id="lives">3</span></p>
  <canvas id="game" width="480" height="360"></canvas>
  <p id="msg">← → 키로 막대를 움직여요</p>
  <button id="start">시작</button>
  <script>
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    const msg = document.getElementById('msg');
    const startBtn = document.getElementById('start');

    let paddle = { x: 200, y: 335, w: 80, h: 10 };
    let ball = { x: 240, y: 320, r: 7, dx: 3, dy: -3 };
    let bricks = [];
    let keys = {};
    let score = 0;
    let lives = 3;
    let running = false;
    let timer = null;

    function makeBricks() {
      bricks = [];
      for (let row = 0; row < 4; row++) {
        for (let col = 0; col < 8; col++) {
          bricks.push({ x: 20 + col * 56, y: 30 + row * 24, w: 50, h: 18, alive: true });
        }
      }
    }

    function resetBall() {
      ball.x = paddle.x + paddle.w / 2;
      ball.y = paddle.y - 15;
      ball.dx = 3;
      ball.dy = -3;
    }

    // 원(공)과 사각형이 겹치는지: 사각형에서 공과 가장 가까운 점까지의 거리
    function hitRect(c, r) {
      const nx = Math.max(r.x, Math.min(c.x, r.x + r.w));
      const ny = Math.max(r.y, Math.min(c.y, r.y + r.h));
      return Math.hypot(c.x - nx, c.y - ny) < c.r;
    }

    function updateInfo() {
      document.getElementById('score').textContent = score;
      document.getElementById('lives').textContent = lives;
    }

    function startGame() {
      clearInterval(timer);
      paddle.x = 200;
      makeBricks();
      resetBall();
      keys = {};
      score = 0;
      lives = 3;
      running = true;
      msg.textContent = '';
      startBtn.textContent = '다시 시작';
      updateInfo();
      timer = setInterval(tick, 16);
    }

    function endGame(text) {
      running = false;
      clearInterval(timer);
      timer = null;
      msg.textContent = text;
      draw();
    }

    function tick() {
      if (!running) return;
      if (keys.ArrowLeft) paddle.x = Math.max(0, paddle.x - 7);
      if (keys.ArrowRight) paddle.x = Math.min(W - paddle.w, paddle.x + 7);

      ball.x += ball.dx;
      ball.y += ball.dy;
      if (ball.x < ball.r || ball.x > W - ball.r) ball.dx = -ball.dx;
      if (ball.y < ball.r) ball.dy = Math.abs(ball.dy);

      // 막대에 맞으면 위로 튕기고, 맞은 위치에 따라 옆 방향이 바뀌어요
      if (ball.dy > 0 && hitRect(ball, paddle)) {
        ball.dy = -Math.abs(ball.dy);
        ball.dx = ((ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2)) * 4;
      }

      for (const b of bricks) {
        if (b.alive && hitRect(ball, b)) {
          b.alive = false;
          ball.dy = -ball.dy;
          score += 10;
          updateInfo();
          break;
        }
      }

      // 바닥에 떨어지면 목숨 -1, 공은 막대 위로 돌아가요
      if (ball.y - ball.r > H) {
        lives = Math.max(0, lives - 1);
        updateInfo();
        if (lives === 0) {
          endGame('💥 게임 오버! 점수: ' + score);
          return;
        }
        resetBall();
      }
      if (bricks.every(function (b) { return !b.alive; })) {
        endGame('🎉 클리어! 점수: ' + score);
        return;
      }
      draw();
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      const colors = ['#f87171', '#fbbf24', '#34d399', '#60a5fa'];
      bricks.forEach(function (b, i) {
        if (!b.alive) return;
        ctx.fillStyle = colors[Math.floor(i / 8)];
        ctx.fillRect(b.x, b.y, b.w, b.h);
      });
      ctx.fillStyle = '#e2e8f0';
      ctx.fillRect(paddle.x, paddle.y, paddle.w, paddle.h);
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
      ctx.fill();
    }

    document.addEventListener('keydown', function (e) {
      if (e.key.startsWith('Arrow') || e.key === ' ') e.preventDefault();
      keys[e.key] = true;
    });
    document.addEventListener('keyup', function (e) {
      keys[e.key] = false;
    });
    startBtn.addEventListener('click', startGame);
    makeBricks();
    draw();
  </script>
</body>
</html>
