<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>카드 짝맞추기</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #f0fdf4; color: #1f2937; padding: 24px; }
    #board { display: grid; grid-template-columns: repeat(4, 80px); gap: 10px; justify-content: center; margin: 16px auto; }
    .card { width: 80px; height: 80px; font-size: 40px; border: none; border-radius: 12px; background: #16a34a; cursor: pointer; }
    .card.open { background: white; border: 2px solid #16a34a; }
    .card.done { background: #bbf7d0; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>🃏 카드 짝맞추기</h1>
  <p>뒤집은 횟수: <span id="moves">0</span> · 찾은 짝: <span id="pairs">0</span>/8</p>
  <div id="board"></div>
  <p id="msg"></p>
  <button id="restart">다시 시작</button>
  <script>
    const emojis = ['🐶', '🐱', '🐰', '🦊', '🐼', '🐸', '🐵', '🐧'];
    const board = document.getElementById('board');
    let cards = [];      // { emoji, open, done, el }
    let picked = [];     // 지금 뒤집힌 카드 두 장
    let lock = false;    // 틀린 카드가 다시 덮일 때까지 클릭 막기
    let moves = 0;
    let pairs = 0;
    let flipTimer = null;

    function shuffle(arr) {
      for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        const t = arr[i]; arr[i] = arr[j]; arr[j] = t;
      }
      return arr;
    }

    function draw() {
      cards.forEach(function (c) {
        c.el.textContent = c.open || c.done ? c.emoji : '';
        c.el.className = 'card' + (c.done ? ' done' : c.open ? ' open' : '');
      });
      document.getElementById('moves').textContent = moves;
      document.getElementById('pairs').textContent = pairs;
    }

    function startGame() {
      clearTimeout(flipTimer);
      board.innerHTML = '';
      cards = shuffle(emojis.concat(emojis)).map(function (emoji) {
        const el = document.createElement('button');
        const card = { emoji: emoji, open: false, done: false, el: el };
        el.addEventListener('click', function () { flip(card); });
        board.appendChild(el);
        return card;
      });
      picked = [];
      lock = false;
      moves = 0;
      pairs = 0;
      document.getElementById('msg').textContent = '';
      draw();
    }

    function flip(card) {
      if (lock || card.open || card.done) return;
      card.open = true;
      picked.push(card);
      if (picked.length === 2) {
        moves += 1;
        const a = picked[0], b = picked[1];
        if (a.emoji === b.emoji) {
          a.done = b.done = true;
          a.open = b.open = false;
          picked = [];
          pairs += 1;
          if (pairs === emojis.length) {
            document.getElementById('msg').textContent = '🎉 다 맞췄어요! ' + moves + '번 만에 성공!';
          }
        } else {
          lock = true;
          flipTimer = setTimeout(function () {
            a.open = b.open = false;
            picked = [];
            lock = false;
            draw();
          }, 700);
        }
      }
      draw();
    }

    document.getElementById('restart').addEventListener('click', startGame);
    startGame();
  </script>
</body>
</html>
