  <style>
    body { font-family: sans-serif; text-align: center; background: #f8fafc; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    .ball { display: inline-block; width: 52px; height: 52px; line-height: 52px; border-radius: 50%; margin: 4px;
      font-size: 22px; font-weight: bold; color: white; }
    #balls { min-height: 64px; margin: 16px; }
  </style>
</head>
<body>
  <h1>🍀 로또 번호 6개</h1>
  <div id="balls"></div>
  <button id="draw">번호 뽑기</button>
  <ol id="list" style="display: inline-block; text-align: left"></ol>
  <script>
    let numbers = [];

    // 번호 범위마다 공 색깔이 달라요
    function ballColor(n) {
      if (n <= 10) return '#eab308';
      if (n <= 20) return '#3b82f6';
      if (n <= 30) return '#ef4444';
      if (n <= 40) return '#6b7280';
      return '#22c55e';
    }

    function pickNumbers() {
      const picked = [];
      while (picked.length < 6) {
        const n = Math.floor(Math.random() * 45) + 1;
        if (!picked.includes(n)) picked.push(n); // 겹치면 다시 뽑아요
      }
      return picked.sort(function (a, b) { return a - b; });
    }

    document.getElementById('draw').addEventListener('click', function () {
      numbers = pickNumbers();
      const box = document.getElementById('balls');
      box.innerHTML = '';
      numbers.forEach(function (n) {
        const span = document.createElement('span');
        span.className = 'ball';
        span.textContent = n;
        span.style.background = ballColor(n);
        box.appendChild(span);
      });
      const li = document.createElement('li');
      li.textContent = numbers.join(', ');
      const list = document.getElementById('list');
      list.prepend(li);
      while (list.children.length > 5) list.lastChild.remove();
    });
  </script>
</body>
</html>
