<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>풍선 터뜨리기</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #fdf4ff; color: #1f2937; padding: 24px; }
    canvas { background: #e0f2fe; border: 3px solid #c026d3; border-radius: 8px; cursor: pointer; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>🎈 풍선 터뜨리기</h1>
  <p>점수: <span id="score">0</span> · 목숨: <span id="lives">5</span></p>
  <canvas id="game" width="400" height="450"></canvas>
  <p id="msg">올라가는 풍선을 클릭해서 터뜨려요! 놓치면 목숨 -1</p>
  <button id="start">시작</button>
  <script>
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    const COLORS = ['#ef4444', '#f59e0b', '#22c55e', '#3b82f6', '#a855f7'];
    const msg = document.getElementById('msg');
    const startBtn = document.getElementById('start');

    let balloons = [];   // { x, y, r, speed, color }
    let score = 0;
    let lives = 5;
    let running = false;
    let timer = null;

    function updateInfo() {
      document.getElementById('score').textContent = score;
      document.getElementById('lives').textContent = lives;
    }

    function pop() {
      const audio = new AudioContext();
      const osc = audio.createOscillator();
      const gain = audio.createGain();
      osc.frequency.value = 600;
      gain.gain.value = 0.1;
      osc.connect(gain);
      gain.connect(audio.destination);
      osc.start();
      osc.stop(audio.currentTime + 0.08);
    }

    function startGame() {
      clearInterval(timer);
      balloons = [];
      score = 0;
      lives = 5;
      running = true;
      msg.textContent = '';
      startBtn.textContent = '다시 시작';
      updateInfo();
      timer = setInterval(tick, 20);
    }

    function gameOver() {
      running = false;
      clearInterval(timer);
      timer = null;
      msg.textContent = '💥 게임 오버! 터뜨린 풍선: ' + score + '개';
    }

    function tick() {
      if (!running) return;
      if (Math.random() < 0.025 + score * 0.0005) {
        balloons.push({ x: 30 + Math.random() * (W - 60), y: H + 30, r: 25, speed: 1.2 + Math.random() * 1.5 + score * 0.02,
          color: COLORS[Math.floor(Math.random() * COLORS.length)] });
      }
      for (let i = balloons.length - 1; i >= 0; i--) {
        balloons[i].y -= balloons[i].speed;
        if (balloons[i].y + balloons[i].r < 0) {
          balloons.splice(i, 1);   // 날아간 풍선은 한 번만 목숨 -1
          lives = Math.max(0, lives - 1);
          updateInfo();
          if (lives === 0) {
            gameOver();
            break;
          }
        }
      }
      draw();
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      for (const b of balloons) {
        ctx.strokeStyle = '#64748b';
        ctx.beginPath();
        ctx.moveTo(b.x, b.y + b.r);
        ctx.lineTo(b.x, b.y + b.r + 25);
        ctx.stroke();
        ctx.fillStyle = b.color;
        ctx.beginPath();
        ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    canvas.addEventListener('mousedown', function (e) {
      if (!running) return;
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;
      // 클릭한 곳과 풍선 중심 사이 거리가 반지름보다 작으면 터져요
      for (let i = balloons.length - 1; i >= 0; i--) {
        if (Math.hypot(mx - balloons[i].x, my - balloons[i].y) < balloons[i].r) {
          balloons.splice(i, 1);
          score += 1;
          updateInfo();
          pop();
          break;
        }
      }
    });
    startBtn.addEventListener('click', startGame);
  </script>
</body>
</html>
