        document.getElementById("msg").textContent = '땡! 정답: ' + String(right);
        document.getElementById("msg").style.color = "#ef4444";
      }
      document.getElementById("score").textContent = '점수: ' + String(score);
      i = (typeof i === 'number' ? i : 0) + 1;
      showQuestion();
    });

    qs = ['대한민국의 수도는?', '물이 끓는 온도는 몇 도?', '무지개는 몇 가지 색?', '1분은 몇 초?'];
    answers = ['서울', '100', '7', '60'];
    i = 1;
    score = 0;
    showQuestion();
  </script>
</body>
</html>
