<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>공 튕기기</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #fef3c7; color: #1f2937; padding: 24px; }
    canvas { background: white; border: 3px solid #f59e0b; border-radius: 8px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>🏓 공 튕기기</h1>
  <p>튕긴 횟수: <span id="score">0</span> · 목숨: <span id="lives">3</span></p>
  <canvas id="game" width="400" height="400"></canvas>
  <p id="msg">← → 키나 마우스로 막대를 움직여 공을 떨어뜨리지 마세요</p>
  <button id="start">시작</button>
  <script>
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    const msg = document.getElementById('msg');
    const startBtn = document.getElementById('start');

    let paddle = { x: 150, y: 370, w: 100, h: 12 };
    let ball = { x: 200, y: 100, r: 10, dx: 3, dy: 3 };
    let keys = {};
    let score = 0;
    let lives = 3;
    let running = false;
    let timer = null;

    function resetBall() {
      ball.x = W / 2;
      ball.y = 80;
      ball.dx = Math.random() < 0.5 ? -3 : 3;
      ball.dy = 3;
    }

    function updateInfo() {
      document.getElementById('score').textContent = score;
      document.getElementById('lives').textContent = lives;
    }

    function startGame() {
      clearInterval(timer);
      paddle.x = 150;
      resetBall();
      keys = {};
      score = 0;
      lives = 3;
      running = true;
      msg.textContent = '';
      startBtn.textContent = '다시 시작';
      updateInfo();
      timer = setInterval(tick, 16);
    }

    function gameOver() {
      running = false;
      clearInterval(timer);
      timer = null;
      msg.textContent = '💥 게임 오버! ' + score + '번 튕겼어요';
    }

    function tick() {
      if (!running) return;
      if (keys.ArrowLeft) paddle.x = Math.max(0, paddle.x - 7);
      if (keys.ArrowRight) paddle.x = Math.min(W - paddle.w, paddle.x + 7);

      ball.x += ball.dx;
      ball.y += ball.dy;
      if (ball.x < ball.r) { ball.x = ball.r; ball.dx = Math.abs(ball.dx); }
      if (ball.x > W - ball.r) { ball.x = W - ball.r; ball.dx = -Math.abs(ball.dx); }
      if (ball.y < ball.r) { ball.y = ball.r; ball.dy = Math.abs(ball.dy); }

      // 공이 막대 위에 닿았는지: x와 y 둘 다 확인
      const overX = ball.x + ball.r > paddle.x && ball.x - ball.r < paddle.x + paddle.w;
      const overY = ball.y + ball.r > paddle.y && ball.y - ball.r < paddle.y + paddle.h;
      if (ball.dy > 0 && overX && overY) {
        ball.dy = -Math.abs(ball.dy) - 0.2; // 조금씩 빨라져요
        ball.y = paddle.y - ball.r;
        score += 1;
        updateInfo();
      }

      if (ball.y - ball.r > H) {
        lives = Math.max(0, lives - 1);
        updateInfo();
        if (lives === 0) {
          gameOver();
        } else {
          resetBall();
        }
      }
      draw();
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      ctx.fillStyle = '#f59e0b';
      ctx.fillRect(paddle.x, paddle.y, paddle.w, paddle.h);
      ctx.fillStyle = '#ef4444';
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
      ctx.fill();
    }

    canvas.addEventListener('mousemove', function (e) {
      if (!running) return;
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      paddle.x = Math.max(0, Math.min(W - paddle.w, mx - paddle.w / 2));
    });
    document.addEventListener('keydown', function (e) {
      if (e.key.startsWith('Arrow') || e.key === ' ') e.preventDefault();
      keys[e.key] = true;
    });
    document.addEventListener('keyup', function (e) {
      keys[e.key] = false;
    });
    startBtn.addEventListener('click', startGame);
    draw();
  </script>
</body>
