      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var secret;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("go").addEventListener('click', function () {
      if ((parseFloat(document.getElementById("guess").value) || 0) == secret) {
        document.getElementById("hint").textContent = '🎉 정답!';
        __beep(523.25, 0.3);
      } else if ((parseFloat(document.getElementById("guess").value) || 0) < secret) {
        document.getElementById("hint").textContent = '🔼 업!';
      } else {
        document.getElementById("hint").textContent = '🔽 다운!';
      }
    });

    secret = mathRandomInt(1, 50);
