      score = (typeof score === 'number' ? score : 0) + 1;
      document.getElementById("sc").textContent = 'Score: ' + String(score);
      if (score > __load('best', 0)) {
        __save('best', score);
        document.getElementById("best").textContent = 'Best: ' + String(score);
      }
    });

