```html
<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>오목</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #fef3c7; color: #1f2937; padding: 24px; }
    canvas { background: #e3b76a; border-radius: 6px; cursor: pointer; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>⚫⚪ 2인용 오목</h1>
  <p id="msg">⚫ 검은 돌 차례</p>
  <canvas id="board" width="450" height="450"></canvas>
  <div><button id="restart">새 게임</button></div>
  <script>
    const N = 15, GAP = 30;
    const canvas = document.getElementById('board');
    const ctx = canvas.getContext('2d');
    const msg = document.getElementById('msg');
    let stones = [];       // 0 빈칸, 1 검은 돌, 2 흰 돌
    let turn = 1;
    let running = true;

    function reset() {
      stones = [];
      for (let r = 0; r < N; r++) stones.push(new Array(N).fill(0));
      turn = 1;
      running = true;
      msg.textContent = '⚫ 검은 돌 차례';
      draw();
    }

    function count(r, c, dr, dc) {
      let n = 0;
      let y = r + dr, x = c + dc;
      while (y >= 0 && y < N && x >= 0 && x < N && stones[y][x] === turn) {
        n += 1;
        y += dr;
        x += dc;
      }
      return n;
    }

    // 가로, 세로, 대각선 두 방향 중 하나라도 5개 이상이면 승리
    function isWin(r, c) {
      const dirs = [[0, 1], [1, 0], [1, 1], [1, -1]];
      return dirs.some(function (d) {
        return 1 + count(r, c, d[0], d[1]) + count(r, c, -d[0], -d[1]) >= 5;
      });
    }

    function place(r, c) {
      if (!running || stones[r][c] !== 0) return;
      stones[r][c] = turn;
      if (isWin(r, c)) {
        running = false;
        msg.textContent = (turn === 1 ? '⚫ 검은 돌' : '⚪ 흰 돌') + ' 승리! 🎉';
      } else {
        turn = turn === 1 ? 2 : 1;
        msg.textContent = turn === 1 ? '⚫ 검은 돌 차례' : '⚪ 흰 돌 차례';
      }
      draw();
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.strokeStyle = '#5b3a10';
      for (let i = 0; i < N; i++) {
        ctx.beginPath();
        ctx.moveTo(GAP / 2, GAP / 2 + i * GAP);
        ctx.lineTo(GAP / 2 + (N - 1) * GAP, GAP / 2 + i * GAP);
        ctx.moveTo(GAP / 2 + i * GAP, GAP / 2);
        ctx.lineTo(GAP / 2 + i * GAP, GAP / 2 + (N - 1) * GAP);
        ctx.stroke();
      }
      for (let r = 0; r < N; r++) {
        for (let c = 0; c < N; c++) {
          if (!stones[r][c]) continue;
          ctx.fillStyle = stones[r][c] === 1 ? '#111' : '#fff';
          ctx.beginPath();
          ctx.arc(GAP / 2 + c * GAP, GAP / 2 + r * GAP, 12, 0, Math.PI * 2);
          ctx.fill();
        }
      }
    }

    canvas.addEventListener('click', function (e) {
      const rect = canvas.getBoundingClientRect();
      // 가장 가까운 교차점 찾기
      const c = Math.round((e.clientX - rect.left - GAP / 2) / GAP);
      const r = Math.round((e.clientY - rect.top - GAP / 2) / GAP);
      if (r >= 0 && r < N && c >= 0 && c < N) place(r, c);
    });
    document.getElementById('restart').addEventListener('click', reset);
    reset();
  </script>
</body>
</html>
