  <p id="listText"></p>
  <h3 id="avgText"></h3>
  <p id="maxMin"></p>
  <script>
    var nums, sum, sorted;

    function listsGetSortCompare(type, direction) {
      var compareFuncs = {
        'NUMERIC': function(a, b) {
            return Number(a) - Number(b); },
        'TEXT': function(a, b) {
            return String(a) > String(b) ? 1 : -1; },
        'IGNORE_CASE': function(a, b) {
            return String(a).toLowerCase() > String(b).toLowerCase() ? 1 : -1; },
      };
      var compare = compareFuncs[type];
      return function(a, b) { return compare(a, b) * direction; };
    }

    document.getElementById("addBtn").addEventListener('click', function () {
      nums.push((parseFloat(document.getElementById("numBox").value) || 0));
      sum = (typeof sum === 'number' ? sum : 0) + (parseFloat(document.getElementById("numBox").value) || 0);
      sorted = nums.slice().sort(listsGetSortCompare("NUMERIC", 1));
      document.getElementById("listText").textContent = '넣은 숫자: ' + String(nums);
      document.getElementById("avgText").textContent = '평균 ' + String(Math.round(sum / nums.length));
      document.getElementById("maxMin").textContent = ['최댓값 ',sorted.slice(-1)[0],' · 최솟값 ',sorted[0]].join('');
      document.getElementById("numBox").value = '';
    });

    nums = [];
    sum = 0;
  </script>
</body>
