      if (x < 20 || x > canvas.width - 20) dx = -dx;
      if (y < 20 || y > canvas.height - 20) dy = -dy;
      ctx.fillStyle = '#22c55e';
      ctx.beginPath();
      ctx.arc(x, y, 20, 0, Math.PI * 2);
      ctx.fill();
    }, 20);
  </script>
