<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>알람 타이머</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #fff7ed; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    input { font-size: 18px; padding: 8px; margin: 4px; width: 70px; }
    #display { font-size: 72px; font-family: monospace; margin: 12px; }
    #msg { font-size: 24px; font-weight: bold; color: #ea580c; min-height: 30px; }
  </style>
</head>
<body>
  <h1>⏲️ 알람 타이머</h1>
  <input id="min" type="number" min="0" max="99" value="1"> 분
  <input id="sec" type="number" min="0" max="59" value="0"> 초
  <div id="display">01:00</div>
  <p id="msg"></p>
  <button id="start">시작</button>
  <button id="pause">일시정지</button>
  <button id="reset">리셋</button>
  <script>
    const display = document.getElementById('display');
    const msg = document.getElementById('msg');
    let remaining = 60;  // 남은 초
    let running = false;
    let timer = null;

    function show() {
      const m = Math.floor(remaining / 60);
      const s = remaining % 60;
      display.textContent = String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
    }

    function readInputs() {
      const m = Math.max(0, Math.floor(Number(document.getElementById('min').value) || 0));
      const s = Math.max(0, Math.floor(Number(document.getElementById('sec').value) || 0));
      return m * 60 + s;
    }

    // 삐삐삐 소리 (오실레이터는 start와 stop으로 켜고 꺼요)
    function beep() {
      const audio = new AudioContext();
      for (let i = 0; i < 3; i++) {
        const osc = audio.createOscillator();
        const gain = audio.createGain();
        osc.type = 'square';
        osc.frequency.value = 880;
        gain.gain.value = 0.08;
        osc.connect(gain);
        gain.connect(audio.destination);
        osc.start(audio.currentTime + i * 0.3);
        osc.stop(audio.currentTime + i * 0.3 + 0.15);
      }
    }

    function tick() {
      if (!running) return;
      remaining -= 1;
      show();
      if (remaining <= 0) {
        remaining = 0;
        running = false;
        clearInterval(timer);
        show();
        msg.textContent = '⏰ 시간 끝!';
        beep();
      }
    }

    document.getElementById('start').addEventListener('click', function () {
      if (running) return;          // 두 번 눌러도 타이머는 하나만
      if (remaining <= 0 || msg.textContent) remaining = readInputs();
      if (remaining <= 0) return;
      msg.textContent = '';
      running = true;
      show();
      clearInterval(timer);
      timer = setInterval(tick, 1000);
    });

    document.getElementById('pause').addEventListener('click', function () {
      running = false;
      clearInterval(timer);
    });

    document.getElementById('reset').addEventListener('click', function () {
      running = false;
      clearInterval(timer);
      remaining = readInputs();
      msg.textContent = '';
      show();
    });

    // 입력값을 바꾸면 화면도 바로 바뀌어요 (돌아가는 중이 아닐 때)
    ['min', 'sec'].forEach(function (id) {
      document.getElementById(id).addEventListener('input', function () {
        if (running) return;
        remaining = readInputs();
        msg.textContent = '';
        show();
      });
    });
  </script>
</body>
</html>
