  <h2 id="pw"></h2>
  <p id="strength"></p>
  <script>
    var n, p;

    function textRandomLetter(text) {
      var x = Math.floor(Math.random() * text.length);
      return text[x];
    }

    document.getElementById("go").addEventListener('click', function () {
      n = (parseFloat(document.getElementById("len").value) || 0);
