<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>Name sorter</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #e0f2fe; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
    ul { display: inline-block; text-align: left; }
    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h2 id="t">Sort names</h2>
  <input id="nm" type="text" placeholder="Name">
  <div id="bx" class="box row">
    <button id="add">Add</button>
    <button id="sort">Sort A-Z</button>
    <button id="clr">Clear</button>
  </div>
  <ul id="view"></ul>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var names, x;

    // 이 함수를 설명하세요...
    function draw() {
      document.getElementById("view").textContent = '';
      for (var x_index in names) {
        x = names[x_index];
        __add("view", x);
      }
    }

    function listsGetSortCompare(type, direction) {
      var compareFuncs = {
        'NUMERIC': function(a, b) {
            return Number(a) - Number(b); },
        'TEXT': function(a, b) {
            return String(a) > String(b) ? 1 : -1; },
        'IGNORE_CASE': function(a, b) {
            return String(a).toLowerCase() > String(b).toLowerCase() ? 1 : -1; },
      };
      var compare = compareFuncs[type];
      return function(a, b) { return compare(a, b) * direction; };
    }

    document.getElementById("add").addEventListener('click', function () {
      if (!!document.getElementById("nm").value.trim().length) {
        names.push(document.getElementById("nm").value.trim());
        document.getElementById("nm").value = '';
        draw();
      }
    });
    document.getElementById("sort").addEventListener('click', function () {
      names = names.slice().sort(listsGetSortCompare("IGNORE_CASE", 1));
      draw();
    });
    document.getElementById("clr").addEventListener('click', function () {
      names = [];
      draw();
    });

    names = [];
  </script>
</body>
</html>
