  <h1>✊✌️✋ 가위바위보 (먼저 3번 이기면 승리)</h1>
  <p id="board">나 0 : 0 컴퓨터</p>
  <div>
    <button class="hand" data-pick="0">✌️</button>
    <button class="hand" data-pick="1">✊</button>
    <button class="hand" data-pick="2">✋</button>
  </div>
  <p id="vs"></p>
  <p id="result"></p>
  <button id="restart">다시 시작</button>
  <script>
    const names = ['✌️ 가위', '✊ 바위', '✋ 보'];
    let me = 0;
    let com = 0;
    let running = true;
    const handBtns = document.querySelectorAll('.hand');
    const result = document.getElementById('result');

    function play(pick) {
      if (!running) return;
      const c = Math.floor(Math.random() * 3);
      document.getElementById('vs').textContent = '나: ' + names[pick] + '  vs  컴퓨터: ' + names[c];
      // 가위(0)는 보(2)를, 바위(1)는 가위(0)를, 보(2)는 바위(1)를 이겨요
      if (pick === c) {
        result.textContent = '비겼어요!';
      } else if ((pick + 2) % 3 === c) {
        me += 1;
        result.textContent = '이겼어요! 😄';
      } else {
        com += 1;
        result.textContent = '졌어요 😢';
      }
      document.getElementById('board').textContent = '나 ' + me + ' : ' + com + ' 컴퓨터';
      if (me === 3 || com === 3) {
        running = false;
        handBtns.forEach(function (b) { b.disabled = true; });
        result.textContent = me === 3 ? '🏆 최종 승리! 축하해요!' : '💥 게임 오버! 컴퓨터가 이겼어요';
      }
    }

    handBtns.forEach(function (b) {
      b.addEventListener('click', function () { play(Number(b.dataset.pick)); });
    });

    document.getElementById('restart').addEventListener('click', function () {
      me = 0;
      com = 0;
      running = true;
      handBtns.forEach(function (b) { b.disabled = false; });
      document.getElementById('board').textContent = '나 0 : 0 컴퓨터';
      document.getElementById('vs').textContent = '';
      result.textContent = '';
    });
  </script>
</body>
</html>
