      a = mathRandomInt(1, 6);
      b = mathRandomInt(1, 6);
      document.getElementById("d1").textContent = a;
      document.getElementById("d2").textContent = b;
      document.getElementById("sum").textContent = '합: ' + String(a + b);
      __add("log", [a,' + ',b].join(''));
      if (a == b) {
        document.getElementById("msg").textContent = '더블!';
      } else {
        document.getElementById("msg").textContent = '';
      }
    });
