<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>똥 피하기</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #fef9c3; color: #1f2937; padding: 24px; }
    canvas { background: #e0f2fe; border: 3px solid #a16207; border-radius: 8px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>💩 똥 피하기</h1>
  <p>점수: <span id="score">0</span> · 목숨: <span id="lives">3</span></p>
  <canvas id="game" width="360" height="420"></canvas>
  <p id="msg">← → 키로 피하세요</p>
  <button id="start">시작</button>
  <script>
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    const msg = document.getElementById('msg');
    const startBtn = document.getElementById('start');

    let player = { x: 165, y: 380, w: 30, h: 30 };
    let poops = [];
    let keys = {};
    let score = 0;
    let lives = 3;
    let safeTime = 0; // 부딪힌 뒤 무적 시간
    let running = false;
    let timer = null;

    // 두 사각형이 겹치는지 (x와 y 모두 검사)
    function overlap(a, b) {
      return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
    }

    function updateInfo() {
      document.getElementById('score').textContent = score;
      document.getElementById('lives').textContent = lives;
    }

    function startGame() {
      clearInterval(timer);
      player.x = 165;
      poops = [];
      keys = {};
      score = 0;
      lives = 3;
      safeTime = 0;
      running = true;
      msg.textContent = '';
      startBtn.textContent = '다시 시작';
      updateInfo();
      timer = setInterval(tick, 20);
    }

    function gameOver() {
      running = false;
      clearInterval(timer);
      timer = null;
      msg.textContent = '💥 게임 오버! 점수: ' + score;
    }

    function tick() {
      if (!running) return;
      if (keys.ArrowLeft) player.x = Math.max(0, player.x - 6);
      if (keys.ArrowRight) player.x = Math.min(W - player.w, player.x + 6);

      // 점수가 오를수록 똥이 더 자주, 더 빨리 떨어져요
      if (Math.random() < 0.03 + score * 0.001) {
        poops.push({ x: Math.random() * (W - 24), y: -24, w: 24, h: 24, speed: 3 + Math.random() * 2 + score * 0.05 });
      }
      for (let i = poops.length - 1; i >= 0; i--) {
        poops[i].y += poops[i].speed;
        if (poops[i].y > H) {
          poops.splice(i, 1);
          score += 1;
          updateInfo();
        }
      }

      if (safeTime > 0) {
        safeTime -= 1;
      } else {
        for (let i = 0; i < poops.length; i++) {
          if (overlap(player, poops[i])) {
            poops.splice(i, 1);
            lives = Math.max(0, lives - 1);
            safeTime = 50;
            updateInfo();
            if (lives === 0) gameOver();
            break;
          }
        }
      }
      draw();
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      ctx.font = '24px sans-serif';
      ctx.textBaseline = 'top';
      for (const p of poops) ctx.fillText('💩', p.x, p.y);
      if (safeTime % 10 < 5) {
        ctx.font = '28px sans-serif';
        ctx.fillText('🏃', player.x, player.y);
      }
    }

    document.addEventListener('keydown', function (e) {
      if (e.key.startsWith('Arrow') || e.key === ' ') e.preventDefault();
      keys[e.key] = true;
    });
    document.addEventListener('keyup', function (e) {
      keys[e.key] = false;
    });
    startBtn.addEventListener('click', startGame);
    draw();
  </script>
</body>
</html>
