    #pet { font-size: 96px; margin: 8px; }
    .bar { width: 240px; height: 18px; background: #e5e7eb; border-radius: 9px; margin: 4px auto 12px; overflow: hidden; }
    .fill { height: 100%; background: #ec4899; }
    #msg { font-size: 22px; font-weight: bold; min-height: 28px; }
  </style>
</head>
<body>
  <h1>🐣 펫 키우기</h1>
  <div id="pet">🐣</div>
  <p>나이: <span id="age">0</span>초</p>
  <div>🍙 배부름 <span id="hungerText">100</span><div class="bar"><div class="fill" id="hunger"></div></div></div>
  <div>⚽ 기분 <span id="funText">100</span><div class="bar"><div class="fill" id="fun"></div></div></div>
  <div>💤 체력 <span id="energyText">100</span><div class="bar"><div class="fill" id="energy"></div></div></div>
  <button id="feed">밥 주기</button>
  <button id="play">놀아 주기</button>
  <button id="sleep">재우기</button>
  <p id="msg"></p>
  <button id="restart">새로 키우기</button>
  <script>
    let stats = { hunger: 100, fun: 100, energy: 100 };
    let age = 0;
    let alive = true;
    let timer = null;
    const msg = document.getElementById('msg');

    function clamp(v) {
      return Math.max(0, Math.min(100, v));
    }

    function show() {
      for (const k in stats) {
        document.getElementById(k).style.width = stats[k] + '%';
        document.getElementById(k + 'Text').textContent = stats[k];
      }
      document.getElementById('age').textContent = age;
      const low = Math.min(stats.hunger, stats.fun, stats.energy);
      let face = age < 30 ? '🐣' : '🐥';
      if (low < 30) face = '😢';
      if (!alive) face = '👻';
      document.getElementById('pet').textContent = face;
    }

    function tick() {
      if (!alive) return;
      age += 1;
      stats.hunger = clamp(stats.hunger - 3);
      stats.fun = clamp(stats.fun - 2);
      stats.energy = clamp(stats.energy - 1);
      if (stats.hunger === 0 || stats.fun === 0 || stats.energy === 0) {
        alive = false;
        clearInterval(timer);
        msg.textContent = '💥 게임 오버! 펫이 떠났어요… ' + age + '초 동안 키웠어요';
      } else if (Math.min(stats.hunger, stats.fun, stats.energy) < 30) {
        msg.textContent = '도와줘요! 😢';
      } else {
        msg.textContent = '';
      }
      show();
    }

    // 버튼을 누르면 하나는 오르고, 다른 건 조금 내려가요
    function care(up, down) {
      if (!alive) return;
      stats[up] = clamp(stats[up] + 20);
      if (down) stats[down] = clamp(stats[down] - 5);
      show();
    }

    function start() {
      clearInterval(timer);
      stats = { hunger: 100, fun: 100, energy: 100 };
      age = 0;
      alive = true;
      msg.textContent = '';
      show();
      timer = setInterval(tick, 1000);
    }

    document.getElementById('feed').addEventListener('click', function () { care('hunger', null); });
    document.getElementById('play').addEventListener('click', function () { care('fun', 'energy'); });
    document.getElementById('sleep').addEventListener('click', function () { care('energy', 'hunger'); });
    document.getElementById('restart').addEventListener('click', start);
    start();
  </script>
</body>
</html>
