<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>점프 게임</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #f1f5f9; color: #1f2937; padding: 24px; }
    canvas { background: white; border: 3px solid #334155; border-radius: 8px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>🦖 점프 게임</h1>
  <p>점수: <span id="score">0</span> · 목숨: <span id="lives">3</span></p>
  <canvas id="game" width="600" height="200"></canvas>
  <p id="msg">스페이스바나 ↑ 키로 점프!</p>
  <button id="start">시작</button>
  <script>
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    const GROUND = 170;
    const msg = document.getElementById('msg');
    const startBtn = document.getElementById('start');

    let player = { x: 60, y: GROUND - 40, w: 36, h: 40, vy: 0 };
    let cactuses = [];
    let score = 0;
    let lives = 3;
    let safeTime = 0;
    let spawnWait = 60;
    let running = false;
    let timer = null;

    function overlap(a, b) {
      return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
    }

    function updateInfo() {
      document.getElementById('score').textContent = score;
      document.getElementById('lives').textContent = lives;
    }

    function jump() {
      if (!running) return;
      if (player.y >= GROUND - player.h) player.vy = -12; // 땅에 있을 때만 점프
    }

    function startGame() {
      clearInterval(timer);
      player.y = GROUND - player.h;
      player.vy = 0;
      cactuses = [];
      score = 0;
      lives = 3;
      safeTime = 0;
      spawnWait = 60;
      running = true;
      msg.textContent = '';
      startBtn.textContent = '다시 시작';
      updateInfo();
      timer = setInterval(tick, 20);
    }

    function gameOver() {
      running = false;
      clearInterval(timer);
      timer = null;
      msg.textContent = '💥 게임 오버! 점수: ' + score;
    }

    function tick() {
      if (!running) return;
      // 중력: y만 바뀌어요
      player.vy += 0.7;
      player.y += player.vy;
      if (player.y > GROUND - player.h) {
        player.y = GROUND - player.h;
        player.vy = 0;
      }

      spawnWait -= 1;
      if (spawnWait <= 0) {
        cactuses.push({ x: W, y: GROUND - 34, w: 20, h: 34 });
        spawnWait = 50 + Math.floor(Math.random() * 60);
      }
      const speed = 6 + score * 0.1;
      for (let i = cactuses.length - 1; i >= 0; i--) {
        cactuses[i].x -= speed;
        if (cactuses[i].x + cactuses[i].w < 0) {
          cactuses.splice(i, 1);
          score += 1;
          updateInfo();
        }
      }

      if (safeTime > 0) {
        safeTime -= 1;
      } else {
        for (const c of cactuses) {
          if (overlap(player, c)) {
            lives = Math.max(0, lives - 1);
            safeTime = 50; // 1초 무적
            updateInfo();
            if (lives === 0) gameOver();
            break;
          }
        }
      }
      draw();
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      ctx.fillStyle = '#94a3b8';
      ctx.fillRect(0, GROUND, W, 3);
      ctx.fillStyle = '#16a34a';
      for (const c of cactuses) ctx.fillRect(c.x, c.y, c.w, c.h);
      if (safeTime % 10 < 5) {
        ctx.fillStyle = '#334155';
        ctx.fillRect(player.x, player.y, player.w, player.h);
      }
    }

    document.addEventListener('keydown', function (e) {
      if (e.key.startsWith('Arrow') || e.key === ' ') e.preventDefault();
      if (e.key === ' ' || e.key === 'ArrowUp') jump();
    });
    canvas.addEventListener('click', jump);
    startBtn.addEventListener('click', startGame);
    draw();
  </script>
</body>
</html>
