  <h1 id="word"></h1>
  <input id="typed" type="text" placeholder="따라 치고 엔터">
  <h2 id="msg"></h2>
  <script>
    var __timers = [];

    var words, w, left, score;

    function listsGetRandomItem(list, remove) {
      var x = Math.floor(Math.random() * list.length);
      if (remove) {
        return list.splice(x, 1)[0];
      } else {
        return list[x];
      }
    }

    // 이 함수를 설명하세요...
    function next() {
      w = listsGetRandomItem(words, false);
      document.getElementById("word").textContent = w;
