    var hp, mhp;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function turn() {
      hp = (typeof hp === 'number' ? hp : 0) + -1 * mathRandomInt(2, 7);
      document.getElementById("meTx").textContent = '나 ❤️ ' + String(hp);
      document.getElementById("monTx").textContent = '몬스터 👾 ' + String(mhp);
      if (mhp <= 0) {
        document.getElementById("result").textContent = '몬스터를 물리쳤다! 🏆';
        __show("btns", "hide");
      } else if (hp <= 0) {
        document.getElementById("result").textContent = '쓰러졌다... 💀';
        __show("btns", "hide");
      }
    }

    document.getElementById("atkBtn").addEventListener('click', function () {
      mhp = (typeof mhp === 'number' ? mhp : 0) + -1 * mathRandomInt(3, 9);
      turn();
    });

    hp = 30;
    mhp = 40;
  </script>
