  <button id="startB">시작</button>
  <button id="hit">지금!</button>
  <script>
    var __timers = [];

    var go, t;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("startB").addEventListener('click', function () {
      go = false;
      document.getElementById("msg").textContent = '기다려... 초록색이 되면 눌러!';
      document.getElementById("msg").style.color = "#111111";
      setTimeout(function () {
        t = 0;
        go = true;
        document.getElementById("msg").textContent = '🟢 지금 눌러!';
        document.getElementById("msg").style.color = "#22c55e";
      }, (mathRandomInt(2, 5)) * 1000);
    });
    __timers.push(setInterval(function () {
      if (go) {
        t = (typeof t === 'number' ? t : 0) + 1;
      }
    }, 20));
    document.getElementById("hit").addEventListener('click', function () {
      if (go) {
        go = false;
        document.getElementById("msg").textContent = ['⏱️ ',t * 20,'ms! 다시 하려면 시작'].join('');
      }
    });

    go = false;
    t = 0;
  </script>
</body>
