<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>커서 따라다니기</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #0f172a; color: #f1f5f9; text-align: center; }
  </style>
</head>
<body>
  <p id="안내">마우스(손가락)를 움직여 보세요. 화살표 키로 🚀를 움직여요</p>
  <h1 id="별">⭐</h1>
  <h1 id="로켓">🚀</h1>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __move(name, x, y) {
      var s = $(name).style;
      s.position = 'absolute';
      s.left = x + 'px';
      s.top = y + 'px';
    }
    function __nudge(name, dx, dy) {
      var el = $(name), s = el.style;
      if (s.position !== 'absolute') {
        var r = el.getBoundingClientRect();
        s.position = 'absolute';
        s.left = (r.left + window.pageXOffset) + 'px';
        s.top = (r.top + window.pageYOffset) + 'px';
      }
      s.left = ((parseFloat(s.left) || 0) + dx) + 'px';
      s.top = ((parseFloat(s.top) || 0) + dy) + 'px';
    }
    function __stay(name) {
      var el = $(name), s = el.style, d = document.documentElement;
      if (s.position !== 'absolute') return;
      var x = Math.max(0, Math.min(parseFloat(s.left) || 0, d.clientWidth - el.offsetWidth));
      var y = Math.max(0, Math.min(parseFloat(s.top) || 0, d.clientHeight - el.offsetHeight));
      s.left = x + 'px';
      s.top = y + 'px';
    }
    var __cx = 0, __cy = 0;
    var __fol = {}, __folOn = false, __moved = false;
    document.addEventListener('pointermove', function () { __moved = true; });
    document.addEventListener('pointerdown', function () { __moved = true; });
    function __folLoop() {
      for (var n in __fol) {
        var el = document.getElementById(n);
        if (!el) { delete __fol[n]; continue; }
        if (!__moved) continue;
        var s = el.style, tx = __cx - el.offsetWidth / 2, ty = __cy - el.offsetHeight / 2;
        if (s.position !== 'absolute') {
          var r = el.getBoundingClientRect();
          s.position = 'absolute';
          s.left = (r.left + window.pageXOffset) + 'px';
          s.top = (r.top + window.pageYOffset) + 'px';
        }
        var x = parseFloat(s.left) || 0, y = parseFloat(s.top) || 0, k = __fol[n] === 'soft' ? 0.15 : 1;
        s.left = (x + (tx - x) * k) + 'px';
        s.top = (y + (ty - y) * k) + 'px';
        s.pointerEvents = 'none';
      }
      requestAnimationFrame(__folLoop);
    }
    function __follow(name, mode) {
      if (mode === 'stop') {
        delete __fol[name];
        var e = document.getElementById(name);
        if (e) e.style.pointerEvents = '';
        return;
      }
      $(name);
      __fol[name] = mode;
      document.body.style.touchAction = 'none';
      if (!__folOn) { __folOn = true; __folLoop(); }
    }

    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowLeft") {
        e.preventDefault();
        __nudge("로켓", -15, 0);
        __stay("로켓");
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowRight") {
        e.preventDefault();
        __nudge("로켓", 15, 0);
        __stay("로켓");
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowUp") {
        e.preventDefault();
        __nudge("로켓", 0, -15);
        __stay("로켓");
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowDown") {
        e.preventDefault();
        __nudge("로켓", 0, 15);
        __stay("로켓");
      }
    });

    __move("로켓", 60, 160);
    __follow("별", "soft");
  </script>
</body>
</html>
